insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','pv',1,1,'Provérbios de Salomão, filho de Davi, rei de Israel;'),
('acf','pv',1,2,'Para se conhecer a sabedoria e a instrução; para se entenderem, as palavras da prudência.'),
('acf','pv',1,3,'Para se receber a instrução do entendimento, a justiça, o juízo e a eqüidade;'),
('acf','pv',1,4,'Para dar aos simples, prudência, e aos moços, conhecimento e bom siso;'),
('acf','pv',1,5,'O sábio ouvirá e crescerá em conhecimento, e o entendido adquirirá sábios conselhos;'),
('acf','pv',1,6,'Para entender os provérbios e sua interpretação; as palavras dos sábios e as suas proposições.'),
('acf','pv',1,7,'O temor do Senhor é o princípio do conhecimento; os loucos desprezam a sabedoria e a instrução.'),
('acf','pv',1,8,'Filho meu, ouve a instrução de teu pai, e não deixes o ensinamento de tua mãe,'),
('acf','pv',1,9,'Porque serão como diadema gracioso em tua cabeça, e colares ao teu pescoço.'),
('acf','pv',1,10,'Filho meu, se os pecadores procuram te atrair com agrados, não aceites.'),
('acf','pv',1,11,'Se disserem: Vem conosco a tocaias de sangue; embosquemos o inocente sem motivo;'),
('acf','pv',1,12,'Traguemo-los vivos, como a sepultura; e inteiros, como os que descem à cova;'),
('acf','pv',1,13,'Acharemos toda sorte de bens preciosos; encheremos as nossas casas de despojos;'),
('acf','pv',1,14,'Lança a tua sorte conosco; teremos todos uma só bolsa!'),
('acf','pv',1,15,'Filho meu, não te ponhas a caminho com eles; desvia o teu pé das suas veredas;'),
('acf','pv',1,16,'Porque os seus pés correm para o mal, e se apressam a derramar sangue.'),
('acf','pv',1,17,'Na verdade é inútil estender-se a rede ante os olhos de qualquer ave.'),
('acf','pv',1,18,'No entanto estes armam ciladas contra o seu próprio sangue; e espreitam suas próprias vidas.'),
('acf','pv',1,19,'São assim as veredas de todo aquele que usa de cobiça: ela põe a perder a alma dos que a possuem.'),
('acf','pv',1,20,'A sabedoria clama lá fora; pelas ruas levanta a sua voz.'),
('acf','pv',1,21,'Nas esquinas movimentadas ela brada; nas entradas das portas e nas cidades profere as suas palavras:'),
('acf','pv',1,22,'Até quando, ó simples, amareis a simplicidade? E vós escarnecedores, desejareis o escárnio? E vós insensatos, odiareis o conhecimento?'),
('acf','pv',1,23,'Atentai para a minha repreensão; pois eis que vos derramarei abundantemente do meu espírito e vos farei saber as minhas palavras.'),
('acf','pv',1,24,'Entretanto, porque eu clamei e recusastes; e estendi a minha mão e não houve quem desse atenção,'),
('acf','pv',1,25,'Antes rejeitastes todo o meu conselho, e não quisestes a minha repreensão,'),
('acf','pv',1,26,'Também de minha parte eu me rirei na vossa perdição e zombarei, em vindo o vosso temor.'),
('acf','pv',1,27,'Vindo o vosso temor como a assolação, e vindo a vossa perdição como uma tormenta, sobrevirá a vós aperto e angústia.'),
('acf','pv',1,28,'Então clamarão a mim, mas eu não responderei; de madrugada me buscarão, porém não me acharão.'),
('acf','pv',1,29,'Porquanto odiaram o conhecimento; e não preferiram o temor do Senhor:'),
('acf','pv',1,30,'Não aceitaram o meu conselho, e desprezaram toda a minha repreensão.'),
('acf','pv',1,31,'Portanto comerão do fruto do seu caminho, e fartar-se-ão dos seus próprios conselhos.'),
('acf','pv',1,32,'Porque o erro dos simples os matará, e o desvario dos insensatos os destruirá.'),
('acf','pv',1,33,'Mas o que me der ouvidos habitará em segurança, e estará livre do temor do mal.'),
('acf','pv',2,1,'Filho meu, se aceitares as minhas palavras, e esconderes contigo os meus mandamentos,'),
('acf','pv',2,2,'Para fazeres o teu ouvido atento à sabedoria; e inclinares o teu coração ao entendimento;'),
('acf','pv',2,3,'Se clamares por conhecimento, e por inteligência alçares a tua voz,'),
('acf','pv',2,4,'Se como a prata a buscares e como a tesouros escondidos a procurares,'),
('acf','pv',2,5,'Então entenderás o temor do Senhor, e acharás o conhecimento de Deus.'),
('acf','pv',2,6,'Porque o Senhor dá a sabedoria; da sua boca é que vem o conhecimento e o entendimento.'),
('acf','pv',2,7,'Ele reserva a verdadeira sabedoria para os retos. Escudo é para os que caminham na sinceridade,'),
('acf','pv',2,8,'Para que guardem as veredas do juízo. Ele preservará o caminho dos seus santos.'),
('acf','pv',2,9,'Então entenderás a justiça, o juízo, a eqüidade e todas as boas veredas.'),
('acf','pv',2,10,'Pois quando a sabedoria entrar no teu coração, e o conhecimento for agradável à tua alma,'),
('acf','pv',2,11,'O bom siso te guardará e a inteligência te conservará;'),
('acf','pv',2,12,'Para te afastar do mau caminho, e do homem que fala coisas perversas;'),
('acf','pv',2,13,'Dos que deixam as veredas da retidão, para andarem pelos caminhos escusos;'),
('acf','pv',2,14,'Que se alegram de fazer mal, e folgam com as perversidades dos maus,'),
('acf','pv',2,15,'Cujas veredas são tortuosas e que se desviam nos seus caminhos;'),
('acf','pv',2,16,'Para te afastar da mulher estranha, sim da estranha que lisonjeia com suas palavras;'),
('acf','pv',2,17,'Que deixa o guia da sua mocidade e se esquece da aliança do seu Deus;'),
('acf','pv',2,18,'Porque a sua casa se inclina para a morte, e as suas veredas para os mortos.'),
('acf','pv',2,19,'Todos os que se dirigem a ela não voltarão e não atinarão com as veredas da vida.'),
('acf','pv',2,20,'Para andares pelos caminhos dos bons, e te conservares nas veredas dos justos.'),
('acf','pv',2,21,'Porque os retos habitarão a terra, e os íntegros permanecerão nela.'),
('acf','pv',2,22,'Mas os ímpios serão arrancados da terra, e os aleivosos serão dela exterminados.'),
('acf','pv',3,1,'Filho meu, não te esqueças da minha lei, e o teu coração guarde os meus mandamentos.'),
('acf','pv',3,2,'Porque eles aumentarão os teus dias e te acrescentarão anos de vida e paz.'),
('acf','pv',3,3,'Não te desamparem a benignidade e a fidelidade; ata-as ao teu pescoço; escreve-as na tábua do teu coração.'),
('acf','pv',3,4,'E acharás graça e bom entendimento aos olhos de Deus e do homem.'),
('acf','pv',3,5,'Confia no Senhor de todo o teu coração, e não te estribes no teu próprio entendimento.'),
('acf','pv',3,6,'Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.'),
('acf','pv',3,7,'Não sejas sábio a teus próprios olhos; teme ao Senhor e aparta-te do mal.'),
('acf','pv',3,8,'Isto será saúde para o teu âmago, e medula para os teus ossos.'),
('acf','pv',3,9,'Honra ao Senhor com os teus bens, e com a primeira parte de todos os teus ganhos;'),
('acf','pv',3,10,'E se encherão os teus celeiros, e transbordarão de vinho os teus lagares.'),
('acf','pv',3,11,'Filho meu, não rejeites a correção do Senhor, nem te enojes da sua repreensão.'),
('acf','pv',3,12,'Porque o Senhor repreende aquele a quem ama, assim como o pai ao filho a quem quer bem.'),
('acf','pv',3,13,'Bem-aventurado o homem que acha sabedoria, e o homem que adquire conhecimento;'),
('acf','pv',3,14,'Porque é melhor a sua mercadoria do que artigos de prata, e maior o seu lucro que o ouro mais fino.'),
('acf','pv',3,15,'Mais preciosa é do que os rubis, e tudo o que mais possas desejar não se pode comparar a ela.'),
('acf','pv',3,16,'Vida longa de dias está na sua mão direita; e na esquerda, riquezas e honra.'),
('acf','pv',3,17,'Os seus caminhos são caminhos de delícias, e todas as suas veredas de paz.'),
('acf','pv',3,18,'É árvore de vida para os que dela tomam, e são bem-aventurados todos os que a retêm.'),
('acf','pv',3,19,'O Senhor, com sabedoria fundou a terra; com entendimento preparou os céus.'),
('acf','pv',3,20,'Pelo seu conhecimento se fenderam os abismos, e as nuvens destilam o orvalho.'),
('acf','pv',3,21,'Filho meu, não se apartem estas coisas dos teus olhos: guarda a verdadeira sabedoria e o bom siso;'),
('acf','pv',3,22,'Porque serão vida para a tua alma, e adorno ao teu pescoço.'),
('acf','pv',3,23,'Então andarás confiante pelo teu caminho, e o teu pé não tropeçará.'),
('acf','pv',3,24,'Quando te deitares, não temerás; ao contrário, o teu sono será suave ao te deitares.'),
('acf','pv',3,25,'Não temas o pavor repentino, nem a investida dos perversos quando vier.'),
('acf','pv',3,26,'Porque o Senhor será a tua esperança; guardará os teus pés de serem capturados.'),
('acf','pv',3,27,'Não deixes de fazer bem a quem o merece, estando em tuas mãos a capacidade de fazê-lo.'),
('acf','pv',3,28,'Não digas ao teu próximo: Vai, e volta amanhã que to darei, se já o tens contigo.'),
('acf','pv',3,29,'Não maquines o mal contra o teu próximo, pois que habita contigo confiadamente.'),
('acf','pv',3,30,'Não contendas com alguém sem causa, se não te fez nenhum mal.'),
('acf','pv',3,31,'Não tenhas inveja do homem violento, nem escolhas nenhum dos seus caminhos.'),
('acf','pv',3,32,'Porque o perverso é abominável ao Senhor, mas com os sinceros ele tem intimidade.'),
('acf','pv',3,33,'A maldição do Senhor habita na casa do ímpio, mas a habitação dos justos abençoará.'),
('acf','pv',3,34,'Certamente ele escarnecerá dos escarnecedores, mas dará graça aos mansos.'),
('acf','pv',3,35,'Os sábios herdarão honra, mas os loucos tomam sobre si vergonha.'),
('acf','pv',4,1,'Ouvi, filhos, a instrução do pai, e estai atentos para conhecerdes a prudência.'),
('acf','pv',4,2,'Pois dou-vos boa doutrina; não deixeis a minha lei.'),
('acf','pv',4,3,'Porque eu era filho tenro na companhia de meu pai, e único diante de minha mãe.'),
('acf','pv',4,4,'E ele me ensinava e me dizia: Retenha o teu coração as minhas palavras; guarda os meus mandamentos, e vive.'),
('acf','pv',4,5,'Adquire sabedoria, adquire inteligência, e não te esqueças nem te apartes das palavras da minha boca.'),
('acf','pv',4,6,'Não a abandones e ela te guardará; ama-a, e ela te protegerá.'),
('acf','pv',4,7,'A sabedoria é a coisa principal; adquire pois a sabedoria, emprega tudo o que possuis na aquisição de entendimento.'),
('acf','pv',4,8,'Exalta-a, e ela te exaltará; e, abraçando-a tu, ela te honrará.'),
('acf','pv',4,9,'Dará à tua cabeça um diadema de graça e uma coroa de glória te entregará.'),
('acf','pv',4,10,'Ouve, filho meu, e aceita as minhas palavras, e se multiplicarão os anos da tua vida.'),
('acf','pv',4,11,'No caminho da sabedoria te ensinei, e por veredas de retidão te fiz andar.'),
('acf','pv',4,12,'Por elas andando, não se embaraçarão os teus passos; e se correres não tropeçarás.'),
('acf','pv',4,13,'Apega-te à instrução e não a largues; guarda-a, porque ela é a tua vida.'),
('acf','pv',4,14,'Não entres pela vereda dos ímpios, nem andes no caminho dos maus.'),
('acf','pv',4,15,'Evita-o; não passes por ele; desvia-te dele e passa de largo.'),
('acf','pv',4,16,'Pois não dormem, se não fizerem mal, e foge deles o sono se não fizerem alguém tropeçar.'),
('acf','pv',4,17,'Porque comem o pão da impiedade, e bebem o vinho da violência.'),
('acf','pv',4,18,'Mas a vereda dos justos é como a luz da aurora, que vai brilhando mais e mais até ser dia perfeito.'),
('acf','pv',4,19,'O caminho dos ímpios é como a escuridão; nem sabem em que tropeçam.'),
('acf','pv',4,20,'Filho meu, atenta para as minhas palavras; às minhas razões inclina o teu ouvido.'),
('acf','pv',4,21,'Não as deixes apartar-se dos teus olhos; guarda-as no íntimo do teu coração.'),
('acf','pv',4,22,'Porque são vida para os que as acham, e saúde para todo o seu corpo.'),
('acf','pv',4,23,'Sobre tudo o que se deve guardar, guarda o teu coração, porque dele procedem as fontes da vida.'),
('acf','pv',4,24,'Desvia de ti a falsidade da boca, e afasta de ti a perversidade dos lábios.'),
('acf','pv',4,25,'Os teus olhos olhem para a frente, e as tuas pálpebras olhem direto diante de ti.'),
('acf','pv',4,26,'Pondera a vereda de teus pés, e todos os teus caminhos sejam bem ordenados!'),
('acf','pv',4,27,'Não declines nem para a direita nem para a esquerda; retira o teu pé do mal.'),
('acf','pv',5,1,'Filho meu, atende à minha sabedoria; à minha inteligência inclina o teu ouvido;'),
('acf','pv',5,2,'Para que guardes os meus conselhos e os teus lábios observem o conhecimento.'),
('acf','pv',5,3,'Porque os lábios da mulher estranha destilam favos de mel, e o seu paladar é mais suave do que o azeite.'),
('acf','pv',5,4,'Mas o seu fim é amargoso como o absinto, agudo como a espada de dois gumes.'),
('acf','pv',5,5,'Os seus pés descem para a morte; os seus passos estão impregnados do inferno.'),
('acf','pv',5,6,'Para que não ponderes os caminhos da vida, as suas andanças são errantes: jamais os conhecerás.'),
('acf','pv',5,7,'Agora, pois, filhos, dai-me ouvidos, e não vos desvieis das palavras da minha boca.'),
('acf','pv',5,8,'Longe dela seja o teu caminho, e não te chegues à porta da sua casa;'),
('acf','pv',5,9,'Para que não dês a outrem a tua honra, e não entregues a cruéis os teus anos de vida;'),
('acf','pv',5,10,'Para que não farte a estranhos o teu esforço, e todo o fruto do teu trabalho vá parar em casa alheia;'),
('acf','pv',5,11,'E no fim venhas a gemer, no consumir-se da tua carne e do teu corpo.'),
('acf','pv',5,12,'E então digas: Como odiei a correção! e o meu coração desprezou a repreensão!'),
('acf','pv',5,13,'E não escutei a voz dos que me ensinavam, nem aos meus mestres inclinei o meu ouvido!'),
('acf','pv',5,14,'No meio da congregação e da assembléia foi que eu me achei em quase todo o mal.'),
('acf','pv',5,15,'Bebe água da tua fonte, e das correntes do teu poço.'),
('acf','pv',5,16,'Derramar-se-iam as tuas fontes por fora, e pelas ruas os ribeiros de águas?'),
('acf','pv',5,17,'Sejam para ti só, e não para os estranhos contigo.'),
('acf','pv',5,18,'Seja bendito o teu manancial, e alegra-te com a mulher da tua mocidade.'),
('acf','pv',5,19,'Como cerva amorosa, e gazela graciosa, os seus seios te saciem todo o tempo; e pelo seu amor sejas atraído perpetuamente.'),
('acf','pv',5,20,'E porque, filho meu, te deixarias atrair por outra mulher, e te abraçarias ao peito de uma estranha?'),
('acf','pv',5,21,'Eis que os caminhos do homem estão perante os olhos do Senhor, e ele pesa todas as suas veredas.'),
('acf','pv',5,22,'Quanto ao ímpio, as suas iniqüidades o prenderão, e com as cordas do seu pecado será detido.'),
('acf','pv',5,23,'Ele morrerá, porque desavisadamente andou, e pelo excesso da sua loucura se perderá.'),
('acf','pv',6,1,'Filho meu, se ficaste por fiador do teu companheiro, se deste a tua mão ao estranho,'),
('acf','pv',6,2,'E te deixaste enredar pelas próprias palavras; e te prendeste nas palavras da tua boca;'),
('acf','pv',6,3,'Faze pois isto agora, filho meu, e livra-te, já que caíste nas mãos do teu companheiro: vai, humilha-te, e importuna o teu companheiro.'),
('acf','pv',6,4,'Não dês sono aos teus olhos, nem deixes adormecer as tuas pálpebras.'),
('acf','pv',6,5,'Livra-te, como a gazela da mão do caçador, e como a ave da mão do passarinheiro.'),
('acf','pv',6,6,'Vai ter com a formiga, ó preguiçoso; olha para os seus caminhos, e sê sábio.'),
('acf','pv',6,7,'Pois ela, não tendo chefe, nem guarda, nem dominador,'),
('acf','pv',6,8,'Prepara no verão o seu pão; na sega ajunta o seu mantimento.'),
('acf','pv',6,9,'Ó preguiçoso, até quando ficarás deitado? Quando te levantarás do teu sono?'),
('acf','pv',6,10,'Um pouco a dormir, um pouco a tosquenejar; um pouco a repousar de braços cruzados;'),
('acf','pv',6,11,'Assim sobrevirá a tua pobreza como o meliante, e a tua necessidade como um homem armado.'),
('acf','pv',6,12,'O homem mau, o homem iníquo tem a boca pervertida.'),
('acf','pv',6,13,'Acena com os olhos, fala com os pés e faz sinais com os dedos.'),
('acf','pv',6,14,'Há no seu coração perversidade, todo o tempo maquina mal; anda semeando contendas.'),
('acf','pv',6,15,'Por isso a sua destruição virá repentinamente; subitamente será quebrantado, sem que haja cura.'),
('acf','pv',6,16,'Estas seis coisas o Senhor odeia, e a sétima a sua alma abomina:'),
('acf','pv',6,17,'Olhos altivos, língua mentirosa, mãos que derramam sangue inocente,'),
('acf','pv',6,18,'O coração que maquina pensamentos perversos, pés que se apressam a correr para o mal,'),
('acf','pv',6,19,'A testemunha falsa que profere mentiras, e o que semeia contendas entre irmãos.'),
('acf','pv',6,20,'Filho meu, guarda o mandamento de teu pai, e não deixes a lei da tua mãe;'),
('acf','pv',6,21,'Ata-os perpetuamente ao teu coração, e pendura-os ao teu pescoço.'),
('acf','pv',6,22,'Quando caminhares, te guiará; quando te deitares, te guardará; quando acordares, falará contigo.'),
('acf','pv',6,23,'Porque o mandamento é lâmpada, e a lei é luz; e as repreensões da correção são o caminho da vida,'),
('acf','pv',6,24,'Para te guardarem da mulher vil, e das lisonjas da estranha.'),
('acf','pv',6,25,'Não cobices no teu coração a sua formosura, nem te prendas aos seus olhos.'),
('acf','pv',6,26,'Porque por causa duma prostituta se chega a pedir um bocado de pão; e a adúltera anda à caça da alma preciosa.'),
('acf','pv',6,27,'Porventura tomará alguém fogo no seu seio, sem que suas vestes se queimem?'),
('acf','pv',6,28,'Ou andará alguém sobre brasas, sem que se queimem os seus pés?'),
('acf','pv',6,29,'Assim ficará o que entrar à mulher do seu próximo; não será inocente todo aquele que a tocar.'),
('acf','pv',6,30,'Não se injuria o ladrão, quando furta para saciar-se, tendo fome;'),
('acf','pv',6,31,'E se for achado pagará o tanto sete vezes; terá de dar todos os bens da sua casa.'),
('acf','pv',6,32,'Assim, o que adultera com uma mulher é falto de entendimento; aquele que faz isso destrói a sua alma.'),
('acf','pv',6,33,'Achará castigo e vilipêndio, e o seu opróbrio nunca se apagará.'),
('acf','pv',6,34,'Porque os ciúmes enfurecerão o marido; de maneira nenhuma perdoará no dia da vingança.'),
('acf','pv',6,35,'Não aceitará nenhum resgate, nem se conformará por mais que aumentes os presentes.'),
('acf','pv',7,1,'Filho meu, guarda as minhas palavras, e esconde dentro de ti os meus mandamentos.'),
('acf','pv',7,2,'Guarda os meus mandamentos e vive; e a minha lei, como a menina dos teus olhos.'),
('acf','pv',7,3,'Ata-os aos teus dedos, escreve-os na tábua do teu coração.'),
('acf','pv',7,4,'Dize à sabedoria: Tu és minha irmã; e à prudência chama de tua parenta,'),
('acf','pv',7,5,'Para que elas te guardem da mulher alheia, da estranha que lisonjeia com as suas palavras.'),
('acf','pv',7,6,'Porque da janela da minha casa, olhando eu por minhas frestas,'),
('acf','pv',7,7,'Vi entre os simples, descobri entre os moços, um moço falto de juízo,'),
('acf','pv',7,8,'Que passava pela rua junto à sua esquina, e seguia o caminho da sua casa;'),
('acf','pv',7,9,'No crepúsculo, à tarde do dia, na tenebrosa noite e na escuridão.'),
('acf','pv',7,10,'E eis que uma mulher lhe saiu ao encontro com enfeites de prostituta, e astúcia de coração.'),
('acf','pv',7,11,'Estava alvoroçada e irrequieta; não paravam em sua casa os seus pés.'),
('acf','pv',7,12,'Foi para fora, depois pelas ruas, e ia espreitando por todos os cantos;'),
('acf','pv',7,13,'E chegou-se para ele e o beijou. Com face impudente lhe disse:'),
('acf','pv',7,14,'Sacrifícios pacíficos tenho comigo; hoje paguei os meus votos.'),
('acf','pv',7,15,'Por isto saí ao teu encontro a buscar diligentemente a tua face, e te achei.'),
('acf','pv',7,16,'Já cobri a minha cama com cobertas de tapeçaria, com obras lavradas, com linho fino do Egito.'),
('acf','pv',7,17,'Já perfumei o meu leito com mirra, aloés e canela.'),
('acf','pv',7,18,'Vem, saciemo-nos de amores até à manhã; alegremo-nos com amores.'),
('acf','pv',7,19,'Porque o marido não está em casa; foi fazer uma longa viagem;'),
('acf','pv',7,20,'Levou na sua mão um saquitel de dinheiro; voltará para casa só no dia marcado.'),
('acf','pv',7,21,'Assim, o seduziu com palavras muito suaves e o persuadiu com as lisonjas dos seus lábios.'),
('acf','pv',7,22,'E ele logo a segue, como o boi que vai para o matadouro, e como vai o insensato para o castigo das prisões;'),
('acf','pv',7,23,'Até que a flecha lhe atravesse o fígado; ou como a ave que se apressa para o laço, e não sabe que está armado contra a sua vida.'),
('acf','pv',7,24,'Agora pois, filhos, dai-me ouvidos, e estai atentos às palavras da minha boca.'),
('acf','pv',7,25,'Não se desvie para os caminhos dela o teu coração, e não te deixes perder nas suas veredas.'),
('acf','pv',7,26,'Porque a muitos feridos derrubou; e são muitíssimos os que por causa dela foram mortos.'),
('acf','pv',7,27,'A sua casa é caminho do inferno que desce para as câmaras da morte.'),
('acf','pv',8,1,'Não clama porventura a sabedoria, e a inteligência não faz ouvir a sua voz?'),
('acf','pv',8,2,'No cume das alturas, junto ao caminho, nas encruzilhadas das veredas se posta.'),
('acf','pv',8,3,'Do lado das portas da cidade, à entrada da cidade, e à entrada das portas está gritando:'),
('acf','pv',8,4,'A vós, ó homens, clamo; e a minha voz se dirige aos filhos dos homens.'),
('acf','pv',8,5,'Entendei, ó simples, a prudência; e vós, insensatos, entendei de coração.'),
('acf','pv',8,6,'Ouvi, porque falarei coisas excelentes; os meus lábios se abrirão para a eqüidade.'),
('acf','pv',8,7,'Porque a minha boca proferirá a verdade, e os meus lábios abominam a impiedade.'),
('acf','pv',8,8,'São justas todas as palavras da minha boca: não há nelas nenhuma coisa tortuosa nem pervertida.'),
('acf','pv',8,9,'Todas elas são retas para aquele que as entende bem, e justas para os que acham o conhecimento.'),
('acf','pv',8,10,'Aceitai a minha correção, e não a prata; e o conhecimento, mais do que o ouro fino escolhido.'),
('acf','pv',8,11,'Porque melhor é a sabedoria do que os rubis; e tudo o que mais se deseja não se pode comparar com ela.'),
('acf','pv',8,12,'Eu, a sabedoria, habito com a prudência, e acho o conhecimento dos conselhos.'),
('acf','pv',8,13,'O temor do Senhor é odiar o mal; a soberba e a arrogância, o mau caminho e a boca perversa, eu odeio.'),
('acf','pv',8,14,'Meu é o conselho e a verdadeira sabedoria; eu sou o entendimento; minha é a fortaleza.'),
('acf','pv',8,15,'Por mim reinam os reis e os príncipes decretam justiça.'),
('acf','pv',8,16,'Por mim governam príncipes e nobres; sim, todos os juízes da terra.'),
('acf','pv',8,17,'Eu amo aos que me amam, e os que cedo me buscarem, me acharão.'),
('acf','pv',8,18,'Riquezas e honra estão comigo; assim como os bens duráveis e a justiça.'),
('acf','pv',8,19,'Melhor é o meu fruto do que o ouro, do que o ouro refinado, e os meus ganhos mais do que a prata escolhida.'),
('acf','pv',8,20,'Faço andar pelo caminho da justiça, no meio das veredas do juízo.'),
('acf','pv',8,21,'Para que faça herdar bens permanentes aos que me amam, e eu encha os seus tesouros.'),
('acf','pv',8,22,'O Senhor me possuiu no princípio de seus caminhos, desde então, e antes de suas obras.'),
('acf','pv',8,23,'Desde a eternidade fui ungida, desde o princípio, antes do começo da terra.'),
('acf','pv',8,24,'Quando ainda não havia abismos, fui gerada, quando ainda não havia fontes carregadas de águas.'),
('acf','pv',8,25,'Antes que os montes se houvessem assentado, antes dos outeiros, eu fui gerada.'),
('acf','pv',8,26,'Ainda ele não tinha feito a terra, nem os campos, nem o princípio do pó do mundo.'),
('acf','pv',8,27,'Quando ele preparava os céus, aí estava eu, quando traçava o horizonte sobre a face do abismo;'),
('acf','pv',8,28,'Quando firmava as nuvens acima, quando fortificava as fontes do abismo,'),
('acf','pv',8,29,'Quando fixava ao mar o seu termo, para que as águas não traspassassem o seu mando, quando compunha os fundamentos da terra.'),
('acf','pv',8,30,'Então eu estava com ele, e era seu arquiteto; era cada dia as suas delícias, alegrando-me perante ele em todo o tempo;'),
('acf','pv',8,31,'Regozijando-me no seu mundo habitável e enchendo-me de prazer com os filhos dos homens.'),
('acf','pv',8,32,'Agora, pois, filhos, ouvi-me, porque bem-aventurados serão os que guardarem os meus caminhos.'),
('acf','pv',8,33,'Ouvi a instrução, e sede sábios, não a rejeiteis.'),
('acf','pv',8,34,'Bem-aventurado o homem que me dá ouvidos, velando às minhas portas cada dia, esperando às ombreiras da minha entrada.'),
('acf','pv',8,35,'Porque o que me achar, achará a vida, e alcançará o favor do Senhor.'),
('acf','pv',8,36,'Mas o que pecar contra mim violentará a sua própria alma; todos os que me odeiam amam a morte.'),
('acf','pv',9,1,'A sabedoria já edificou a sua casa, já lavrou as suas sete colunas.'),
('acf','pv',9,2,'Já abateu os seus animais e misturou o seu vinho, e já preparou a sua mesa.'),
('acf','pv',9,3,'Já ordenou às suas criadas, e está convidando desde as alturas da cidade, dizendo:'),
('acf','pv',9,4,'Quem é simples, volte-se para cá. Aos faltos de senso diz:'),
('acf','pv',9,5,'Vinde, comei do meu pão, e bebei do vinho que tenho misturado.'),
('acf','pv',9,6,'Deixai os insensatos e vivei; e andai pelo caminho do entendimento.'),
('acf','pv',9,7,'O que repreende o escarnecedor, toma afronta para si; e o que censura o ímpio recebe a sua mancha.'),
('acf','pv',9,8,'Não repreendas o escarnecedor, para que não te odeie; repreende o sábio, e ele te amará.'),
('acf','pv',9,9,'Dá instrução ao sábio, e ele se fará mais sábio; ensina o justo e ele aumentará em entendimento.'),
('acf','pv',9,10,'O temor do Senhor é o princípio da sabedoria, e o conhecimento do Santo a prudência.'),
('acf','pv',9,11,'Porque por meu intermédio se multiplicam os teus dias, e anos de vida se te aumentarão.'),
('acf','pv',9,12,'Se fores sábio, para ti serás sábio; e, se fores escarnecedor, só tu o suportarás.'),
('acf','pv',9,13,'A mulher louca é alvoroçadora; é simples e nada sabe.'),
('acf','pv',9,14,'Assenta-se à porta da sua casa numa cadeira, nas alturas da cidade,'),
('acf','pv',9,15,'E põe-se a chamar aos que vão pelo caminho, e que passam reto pelas veredas, dizendo:'),
('acf','pv',9,16,'Quem é simples, volte-se para cá. E aos faltos de entendimento ela diz:'),
('acf','pv',9,17,'As águas roubadas são doces, e o pão tomado às escondidas é agradável.'),
('acf','pv',9,18,'Mas não sabem que ali estão os mortos; os seus convidados estão nas profundezas do inferno.'),
('acf','pv',10,1,'Provérbios de Salomão: O filho sábio alegra a seu pai, mas o filho insensato é a tristeza de sua mãe.'),
('acf','pv',10,2,'Os tesouros da impiedade de nada aproveitam; mas a justiça livra da morte.'),
('acf','pv',10,3,'O Senhor não deixa o justo passar fome, mas rechaça a aspiração dos perversos.'),
('acf','pv',10,4,'O que trabalha com mão displicente empobrece, mas a mão dos diligentes enriquece.'),
('acf','pv',10,5,'O que ajunta no verão é filho ajuizado, mas o que dorme na sega é filho que envergonha.'),
('acf','pv',10,6,'Bênçãos há sobre a cabeça do justo, mas a violência cobre a boca dos perversos.'),
('acf','pv',10,7,'A memória do justo é abençoada, mas o nome dos perversos apodrecerá.'),
('acf','pv',10,8,'O sábio de coração aceita os mandamentos, mas o insensato de lábios ficará transtornado.'),
('acf','pv',10,9,'Quem anda em sinceridade, anda seguro; mas o que perverte os seus caminhos ficará conhecido.'),
('acf','pv',10,10,'O que acena com os olhos causa dores, e o tolo de lábios ficará transtornado.'),
('acf','pv',10,11,'A boca do justo é fonte de vida, mas a violência cobre a boca dos perversos.'),
('acf','pv',10,12,'O ódio excita contendas, mas o amor cobre todos os pecados.'),
('acf','pv',10,13,'Nos lábios do entendido se acha a sabedoria, mas a vara é para as costas do falto de entendimento.'),
('acf','pv',10,14,'Os sábios entesouram a sabedoria; mas a boca do tolo o aproxima da ruína.'),
('acf','pv',10,15,'Os bens do rico são a sua cidade forte, a pobreza dos pobres a sua ruína.'),
('acf','pv',10,16,'A obra do justo conduz à vida, o fruto do perverso, ao pecado.'),
('acf','pv',10,17,'O caminho para a vida é daquele que guarda a instrução, mas o que deixa a repreensão comete erro.'),
('acf','pv',10,18,'O que encobre o ódio tem lábios falsos, e o que divulga má fama é um insensato.'),
('acf','pv',10,19,'Na multidão de palavras não falta pecado, mas o que modera os seus lábios é sábio.'),
('acf','pv',10,20,'Prata escolhida é a língua do justo; o coração dos perversos é de nenhum valor.'),
('acf','pv',10,21,'Os lábios do justo apascentam a muitos, mas os tolos morrem por falta de entendimento.'),
('acf','pv',10,22,'A bênção do Senhor é que enriquece; e não traz consigo dores.'),
('acf','pv',10,23,'Para o tolo, o cometer desordem é divertimento; mas para o homem entendido é o ter sabedoria.'),
('acf','pv',10,24,'Aquilo que o perverso teme sobrevirá a ele, mas o desejo dos justos será concedido.'),
('acf','pv',10,25,'Como passa a tempestade, assim desaparece o perverso, mas o justo tem fundamento perpétuo.'),
('acf','pv',10,26,'Como vinagre para os dentes, como fumaça para os olhos, assim é o preguiçoso para aqueles que o mandam.'),
('acf','pv',10,27,'O temor do Senhor aumenta os dias, mas os perversos terão os anos da vida abreviados.'),
('acf','pv',10,28,'A esperança dos justos é alegria, mas a expectação dos perversos perecerá.'),
('acf','pv',10,29,'O caminho do Senhor é fortaleza para os retos, mas ruína para os que praticam a iniqüidade.'),
('acf','pv',10,30,'O justo nunca jamais será abalado, mas os perversos não habitarão a terra.'),
('acf','pv',10,31,'A boca do justo jorra sabedoria, mas a língua da perversidade será cortada.'),
('acf','pv',10,32,'Os lábios do justo sabem o que agrada, mas a boca dos perversos, só perversidades.'),
('acf','pv',11,1,'Balança enganosa é abominação para o SENHOR, mas o peso justo é o seu prazer.'),
('acf','pv',11,2,'Em vindo a soberba, virá também a afronta; mas com os humildes está a sabedoria.'),
('acf','pv',11,3,'A sinceridade dos íntegros os guiará, mas a perversidade dos aleivosos os destruirá.'),
('acf','pv',11,4,'De nada aproveitam as riquezas no dia da ira, mas a justiça livra da morte.'),
('acf','pv',11,5,'A justiça do sincero endireitará o seu caminho, mas o perverso pela sua falsidade cairá.'),
('acf','pv',11,6,'A justiça dos virtuosos os livrará, mas na sua perversidade serão apanhados os iníquos.'),
('acf','pv',11,7,'Morrendo o homem perverso perece sua esperança, e acaba-se a expectação de riquezas.'),
('acf','pv',11,8,'O justo é libertado da angústia, e vem o ímpio para o seu lugar.'),
('acf','pv',11,9,'O hipócrita com a boca destrói o seu próximo, mas os justos se libertam pelo conhecimento.'),
('acf','pv',11,10,'No bem dos justos exulta a cidade; e perecendo os ímpios, há júbilo.'),
('acf','pv',11,11,'Pela bênção dos homens de bem a cidade se exalta, mas pela boca dos perversos é derrubada.'),
('acf','pv',11,12,'O que despreza o seu próximo carece de entendimento, mas o homem entendido se mantém calado.'),
('acf','pv',11,13,'O mexeriqueiro revela o segredo, mas o fiel de espírito o mantém em oculto.'),
('acf','pv',11,14,'Não havendo sábios conselhos, o povo cai, mas na multidão de conselhos há segurança.'),
('acf','pv',11,15,'Decerto sofrerá severamente aquele que fica por fiador do estranho, mas o que evita a fiança estará seguro.'),
('acf','pv',11,16,'A mulher graciosa guarda a honra como os violentos guardam as riquezas.'),
('acf','pv',11,17,'O homem bom cuida bem de si mesmo, mas o cruel prejudica o seu corpo.'),
('acf','pv',11,18,'O ímpio faz obra falsa, mas para o que semeia justiça haverá galardão fiel.'),
('acf','pv',11,19,'Como a justiça encaminha para a vida, assim o que segue o mal vai para a sua morte.'),
('acf','pv',11,20,'Abominação ao Senhor são os perversos de coração, mas os de caminho sincero são o seu deleite.'),
('acf','pv',11,21,'Ainda que junte as mãos, o mau não ficará impune, mas a semente dos justos será liberada.'),
('acf','pv',11,22,'Como jóia de ouro no focinho de uma porca, assim é a mulher formosa que não tem discrição.'),
('acf','pv',11,23,'O desejo dos justos é tão somente para o bem, mas a esperança dos ímpios é criar contrariedades.'),
('acf','pv',11,24,'Ao que distribui mais se lhe acrescenta, e ao que retém mais do que é justo, é para a sua perda.'),
('acf','pv',11,25,'A alma generosa prosperará e aquele que atende também será atendido.'),
('acf','pv',11,26,'Ao que retém o trigo o povo amaldiçoa, mas bênção haverá sobre a cabeça do que o vende.'),
('acf','pv',11,27,'O que cedo busca o bem, busca favor, mas o que procura o mal, esse lhe sobrevirá.'),
('acf','pv',11,28,'Aquele que confia nas suas riquezas cairá, mas os justos reverdecerão como a folhagem.'),
('acf','pv',11,29,'O que perturba a sua casa herdará o vento, e o tolo será servo do sábio de coração.'),
('acf','pv',11,30,'O fruto do justo é árvore de vida, e o que ganha almas é sábio.'),
('acf','pv',11,31,'Eis que o justo recebe na terra a retribuição; quanto mais o ímpio e o pecador!'),
('acf','pv',12,1,'O que ama a instrução ama o conhecimento, mas o que odeia a repreensão é estúpido.'),
('acf','pv',12,2,'O homem de bem alcançará o favor do Senhor, mas ao homem de intenções perversas ele condenará.'),
('acf','pv',12,3,'O homem não se estabelecerá pela impiedade, mas a raiz dos justos não será removida.'),
('acf','pv',12,4,'A mulher virtuosa é a coroa do seu marido, mas a que o envergonha é como podridão nos seus ossos.'),
('acf','pv',12,5,'Os pensamentos dos justos são retos, mas os conselhos dos ímpios, engano.'),
('acf','pv',12,6,'As palavras dos ímpios são ciladas para derramar sangue, mas a boca dos retos os livrará.'),
('acf','pv',12,7,'Os ímpios serão transtornados e não subsistirão, mas a casa dos justos permanecerá.'),
('acf','pv',12,8,'Cada qual será louvado segundo o seu entendimento, mas o perverso de coração estará em desprezo.'),
('acf','pv',12,9,'Melhor é o que se estima em pouco, e tem servos, do que o que se vangloria e tem falta de pão.'),
('acf','pv',12,10,'O justo tem consideração pela vida dos seus animais, mas as afeições dos ímpios são cruéis.'),
('acf','pv',12,11,'O que lavra a sua terra se fartará de pão; mas o que segue os ociosos é falto de juízo.'),
('acf','pv',12,12,'O ímpio deseja a rede dos maus, mas a raiz dos justos produz o seu fruto.'),
('acf','pv',12,13,'O ímpio se enlaça na transgressão dos lábios, mas o justo sairá da angústia.'),
('acf','pv',12,14,'Cada um se fartará do fruto da sua boca, e da obra das suas mãos o homem receberá a recompensa.'),
('acf','pv',12,15,'O caminho do insensato é reto aos seus próprios olhos, mas o que dá ouvidos ao conselho é sábio.'),
('acf','pv',12,16,'A ira do insensato se conhece no mesmo dia, mas o prudente encobre a afronta.'),
('acf','pv',12,17,'O que diz a verdade manifesta a justiça, mas a falsa testemunha diz engano.'),
('acf','pv',12,18,'Há alguns que falam como que espada penetrante, mas a língua dos sábios é saúde.'),
('acf','pv',12,19,'O lábio da verdade permanece para sempre, mas a língua da falsidade, dura por um só momento.'),
('acf','pv',12,20,'No coração dos que maquinam o mal há engano, mas os que aconselham a paz têm alegria.'),
('acf','pv',12,21,'Nenhum agravo sobrevirá ao justo, mas os ímpios ficam cheios de mal.'),
('acf','pv',12,22,'Os lábios mentirosos são abomináveis ao Senhor, mas os que agem fielmente são o seu deleite.'),
('acf','pv',12,23,'O homem prudente encobre o conhecimento, mas o coração dos tolos proclama a estultícia.'),
('acf','pv',12,24,'A mão dos diligentes dominará, mas os negligentes serão tributários.'),
('acf','pv',12,25,'A ansiedade no coração deixa o homem abatido, mas uma boa palavra o alegra.'),
('acf','pv',12,26,'O justo é mais excelente do que o seu próximo, mas o caminho dos ímpios faz errar.'),
('acf','pv',12,27,'O preguiçoso deixa de assar a sua caça, mas ser diligente é o precioso bem do homem.'),
('acf','pv',12,28,'Na vereda da justiça está a vida, e no caminho da sua carreira não há morte.'),
('acf','pv',13,1,'O filho sábio atende à instrução do pai; mas o escarnecedor não ouve a repreensão.'),
('acf','pv',13,2,'Do fruto da boca cada um comerá o bem, mas a alma dos prevaricadores comerá a violência.'),
('acf','pv',13,3,'O que guarda a sua boca conserva a sua alma, mas o que abre muito os seus lábios se destrói.'),
('acf','pv',13,4,'A alma do preguiçoso deseja, e coisa nenhuma alcança, mas a alma dos diligentes se farta.'),
('acf','pv',13,5,'O justo odeia a palavra de mentira, mas o ímpio faz vergonha e se confunde.'),
('acf','pv',13,6,'A justiça guarda ao que é de caminho certo, mas a impiedade transtornará o pecador.'),
('acf','pv',13,7,'Há alguns que se fazem de ricos, e não têm coisa nenhuma, e outros que se fazem de pobres e têm muitas riquezas.'),
('acf','pv',13,8,'O resgate da vida de cada um são as suas riquezas, mas o pobre não ouve ameaças.'),
('acf','pv',13,9,'A luz dos justos alegra, mas a candeia dos ímpios se apagará.'),
('acf','pv',13,10,'Da soberba só provém a contenda, mas com os que se aconselham se acha a sabedoria.'),
('acf','pv',13,11,'A riqueza de procedência vã diminuirá, mas quem a ajunta com o próprio trabalho a aumentará.'),
('acf','pv',13,12,'A esperança adiada desfalece o coração, mas o desejo atendido é árvore de vida.'),
('acf','pv',13,13,'O que despreza a palavra perecerá, mas o que teme o mandamento será galardoado.'),
('acf','pv',13,14,'A doutrina do sábio é uma fonte de vida para se desviar dos laços da morte.'),
('acf','pv',13,15,'O bom entendimento favorece, mas o caminho dos prevaricadores é áspero.'),
('acf','pv',13,16,'Todo prudente procede com conhecimento, mas o insensato espraia a sua loucura.'),
('acf','pv',13,17,'O que prega a maldade cai no mal, mas o embaixador fiel é saúde.'),
('acf','pv',13,18,'Pobreza e afronta virão ao que rejeita a instrução, mas o que guarda a repreensão será honrado.'),
('acf','pv',13,19,'O desejo que se alcança deleita a alma, mas apartar-se do mal é abominável para os insensatos.'),
('acf','pv',13,20,'O que anda com os sábios ficará sábio, mas o companheiro dos tolos será destruído.'),
('acf','pv',13,21,'O mal perseguirá os pecadores, mas os justos serão galardoados com o bem.'),
('acf','pv',13,22,'O homem de bem deixa uma herança aos filhos de seus filhos, mas a riqueza do pecador é depositada para o justo.'),
('acf','pv',13,23,'O pobre, do sulco da terra, tira mantimento em abundância; mas há os que se consomem por falta de juízo.'),
('acf','pv',13,24,'O que não faz uso da vara odeia seu filho, mas o que o ama, desde cedo o castiga.'),
('acf','pv',13,25,'O justo come até ficar satisfeito, mas o ventre dos ímpios passará necessidade.'),
('acf','pv',14,1,'Toda mulher sábia edifica a sua casa; mas a tola a derruba com as próprias mãos.'),
('acf','pv',14,2,'O que anda na retidão teme ao Senhor, mas o que se desvia de seus caminhos o despreza.'),
('acf','pv',14,3,'Na boca do tolo está a punição da soberba, mas os sábios se conservam pelos próprios lábios.'),
('acf','pv',14,4,'Não havendo bois o estábulo fica limpo, mas pela força do boi há abundância de colheita.'),
('acf','pv',14,5,'A verdadeira testemunha não mentirá, mas a testemunha falsa se desboca em mentiras.'),
('acf','pv',14,6,'O escarnecedor busca sabedoria e não acha nenhuma, para o prudente, porém, o conhecimento é fácil.'),
('acf','pv',14,7,'Desvia-te do homem insensato, porque nele não acharás lábios de conhecimento.'),
('acf','pv',14,8,'A sabedoria do prudente é entender o seu caminho, mas a estultícia dos insensatos é engano.'),
('acf','pv',14,9,'Os insensatos zombam do pecado, mas entre os retos há benevolência.'),
('acf','pv',14,10,'O coração conhece a sua própria amargura, e o estranho não participará no íntimo da sua alegria.'),
('acf','pv',14,11,'A casa dos ímpios se desfará, mas a tenda dos retos florescerá.'),
('acf','pv',14,12,'Há um caminho que ao homem parece direito, mas o fim dele são os caminhos da morte.'),
('acf','pv',14,13,'Até no riso o coração sente dor e o fim da alegria é tristeza.'),
('acf','pv',14,14,'O que no seu coração comete deslize, se enfada dos seus caminhos, mas o homem bom fica satisfeito com o seu proceder.'),
('acf','pv',14,15,'O simples dá crédito a cada palavra, mas o prudente atenta para os seus passos.'),
('acf','pv',14,16,'O sábio teme, e desvia-se do mal, mas o tolo se encoleriza, e dá-se por seguro.'),
('acf','pv',14,17,'O que se indigna à toa fará doidices, e o homem de maus intentos será odiado.'),
('acf','pv',14,18,'Os simples herdarão a estultícia, mas os prudentes serão coroados de conhecimento.'),
('acf','pv',14,19,'Os maus inclinam-se diante dos bons, e os ímpios diante das portas dos justos.'),
('acf','pv',14,20,'O pobre é odiado até pelo seu próximo, porém os amigos dos ricos são muitos.'),
('acf','pv',14,21,'O que despreza ao seu próximo peca, mas o que se compadece dos humildes é bem-aventurado.'),
('acf','pv',14,22,'Porventura não erram os que praticam o mal? mas beneficência e fidelidade haverá para os que praticam o bem.'),
('acf','pv',14,23,'Em todo trabalho há proveito, mas ficar só em palavras leva à pobreza.'),
('acf','pv',14,24,'A coroa dos sábios é a sua riqueza, a estultícia dos tolos é só estultícia.'),
('acf','pv',14,25,'A testemunha verdadeira livra as almas, mas o que se desboca em mentiras é enganador.'),
('acf','pv',14,26,'No temor do Senhor há firme confiança e ele será um refúgio para seus filhos.'),
('acf','pv',14,27,'O temor do Senhor é fonte de vida, para desviar dos laços da morte.'),
('acf','pv',14,28,'Na multidão do povo está a glória do rei, mas na falta de povo a ruína do príncipe.'),
('acf','pv',14,29,'O longânimo é grande em entendimento, mas o que é de espírito impaciente mostra a sua loucura.'),
('acf','pv',14,30,'O sentimento sadio é vida para o corpo, mas a inveja é podridão para os ossos.'),
('acf','pv',14,31,'O que oprime o pobre insulta àquele que o criou, mas o que se compadece do necessitado o honra.'),
('acf','pv',14,32,'Pela sua própria malícia é lançado fora o perverso, mas o justo até na morte se mantém confiante.'),
('acf','pv',14,33,'No coração do prudente a sabedoria permanece, mas o que está no interior dos tolos se faz conhecido.'),
('acf','pv',14,34,'A justiça exalta os povos, mas o pecado é a vergonha das nações.'),
('acf','pv',14,35,'O rei se alegra no servo prudente, mas sobre o que o envergonha cairá o seu furor.'),
('acf','pv',15,1,'A resposta branda desvia o furor, mas a palavra dura suscita a ira.'),
('acf','pv',15,2,'A língua dos sábios adorna a sabedoria, mas a boca dos tolos derrama a estultícia.'),
('acf','pv',15,3,'Os olhos do Senhor estão em todo lugar, contemplando os maus e os bons.'),
('acf','pv',15,4,'A língua benigna é árvore de vida, mas a perversidade nela deprime o espírito.'),
('acf','pv',15,5,'O tolo despreza a instrução de seu pai, mas o que observa a repreensão se haverá prudentemente.'),
('acf','pv',15,6,'Na casa do justo há um grande tesouro, mas nos ganhos do ímpio há perturbação.'),
('acf','pv',15,7,'Os lábios dos sábios derramam o conhecimento, mas o coração dos tolos não faz assim.'),
('acf','pv',15,8,'O sacrifício dos ímpios é abominável ao Senhor, mas a oração dos retos é o seu contentamento.'),
('acf','pv',15,9,'O caminho do ímpio é abominável ao Senhor, mas ao que segue a justiça ele ama.'),
('acf','pv',15,10,'Correção severa há para o que deixa a vereda, e o que odeia a repreensão morrerá.'),
('acf','pv',15,11,'O inferno e a perdição estão perante o Senhor; quanto mais os corações dos filhos dos homens?'),
('acf','pv',15,12,'O escarnecedor não ama aquele que o repreende, nem se chegará aos sábios.'),
('acf','pv',15,13,'O coração alegre aformoseia o rosto, mas pela dor do coração o espírito se abate.'),
('acf','pv',15,14,'O coração entendido buscará o conhecimento, mas a boca dos tolos se apascentará de estultícia.'),
('acf','pv',15,15,'Todos os dias do oprimido são maus, mas o coração alegre é um banquete contínuo.'),
('acf','pv',15,16,'Melhor é o pouco com o temor do Senhor, do que um grande tesouro onde há inquietação.'),
('acf','pv',15,17,'Melhor é a comida de hortaliça, onde há amor, do que o boi cevado, e com ele o ódio.'),
('acf','pv',15,18,'O homem iracundo suscita contendas, mas o longânimo apaziguará a luta.'),
('acf','pv',15,19,'O caminho do preguiçoso é cercado de espinhos, mas a vereda dos retos é bem aplanada.'),
('acf','pv',15,20,'O filho sábio alegra seu pai, mas o homem insensato despreza a sua mãe.'),
('acf','pv',15,21,'A estultícia é alegria para o que carece de entendimento, mas o homem entendido anda retamente.'),
('acf','pv',15,22,'Quando não há conselhos os planos se dispersam, mas havendo muitos conselheiros eles se firmam.'),
('acf','pv',15,23,'O homem se alegra em responder bem, e quão boa é a palavra dita a seu tempo!'),
('acf','pv',15,24,'Para o entendido, o caminho da vida leva para cima, para que se desvie do inferno em baixo.'),
('acf','pv',15,25,'O Senhor desarraiga a casa dos soberbos, mas estabelece o termo da viúva.'),
('acf','pv',15,26,'Abomináveis são para o Senhor os pensamentos do mau, mas as palavras dos puros são aprazíveis.'),
('acf','pv',15,27,'O que agir com avareza perturba a sua casa, mas o que odeia presentes viverá.'),
('acf','pv',15,28,'O coração do justo medita no que há de responder, mas a boca dos ímpios jorra coisas más.'),
('acf','pv',15,29,'O Senhor está longe dos ímpios, mas a oração dos justos escutará.'),
('acf','pv',15,30,'A luz dos olhos alegra o coração, a boa notícia fortalece os ossos.'),
('acf','pv',15,31,'Os ouvidos que atendem à repreensão da vida farão a sua morada no meio dos sábios.'),
('acf','pv',15,32,'O que rejeita a instrução menospreza a própria alma, mas o que escuta a repreensão adquire entendimento.'),
('acf','pv',15,33,'O temor do Senhor é a instrução da sabedoria, e precedendo a honra vai a humildade.'),
('acf','pv',16,1,'Do homem são as preparações do coração, mas do SENHOR a resposta da língua.'),
('acf','pv',16,2,'Todos os caminhos do homem são puros aos seus olhos, mas o Senhor pesa o espírito.'),
('acf','pv',16,3,'Confia ao Senhor as tuas obras, e teus pensamentos serão estabelecidos.'),
('acf','pv',16,4,'O Senhor fez todas as coisas para atender aos seus próprios desígnios, até o ímpio para o dia do mal.'),
('acf','pv',16,5,'Abominação é ao Senhor todo o altivo de coração; não ficará impune mesmo de mãos postas.'),
('acf','pv',16,6,'Pela misericórdia e verdade a iniqüidade é perdoada, e pelo temor do Senhor os homens se desviam do pecado.'),
('acf','pv',16,7,'Sendo os caminhos do homem agradáveis ao Senhor, até a seus inimigos faz que tenham paz com ele.'),
('acf','pv',16,8,'Melhor é o pouco com justiça, do que a abundância de bens com injustiça.'),
('acf','pv',16,9,'O coração do homem planeja o seu caminho, mas o Senhor lhe dirige os passos.'),
('acf','pv',16,10,'Nos lábios do rei se acha a sentença divina; a sua boca não transgride quando julga.'),
('acf','pv',16,11,'O peso e a balança justos são do Senhor; obra sua são os pesos da bolsa.'),
('acf','pv',16,12,'Abominação é aos reis praticarem impiedade, porque com justiça é que se estabelece o trono.'),
('acf','pv',16,13,'Os lábios de justiça são o contentamento dos reis; eles amarão o que fala coisas retas.'),
('acf','pv',16,14,'O furor do rei é mensageiro da morte, mas o homem sábio o apaziguará.'),
('acf','pv',16,15,'No semblante iluminado do rei está a vida, e a sua benevolência é como a nuvem da chuva serôdia.'),
('acf','pv',16,16,'Quão melhor é adquirir a sabedoria do que o ouro! e quão mais excelente é adquirir a prudência do que a prata!'),
('acf','pv',16,17,'Os retos fazem o seu caminho desviar-se do mal; o que guarda o seu caminho preserva a sua alma.'),
('acf','pv',16,18,'A soberba precede a ruína, e a altivez do espírito precede a queda.'),
('acf','pv',16,19,'Melhor é ser humilde de espírito com os mansos, do que repartir o despojo com os soberbos.'),
('acf','pv',16,20,'O que atenta prudentemente para o assunto achará o bem, e o que confia no Senhor será bem-aventurado.'),
('acf','pv',16,21,'O sábio de coração será chamado prudente, e a doçura dos lábios aumentará o ensino.'),
('acf','pv',16,22,'O entendimento para aqueles que o possuem, é uma fonte de vida, mas a instrução dos tolos é a sua estultícia.'),
('acf','pv',16,23,'O coração do sábio instrui a sua boca, e aumenta o ensino dos seus lábios.'),
('acf','pv',16,24,'As palavras suaves são favos de mel, doces para a alma, e saúde para os ossos.'),
('acf','pv',16,25,'Há um caminho que parece direito ao homem, mas o seu fim são os caminhos da morte.'),
('acf','pv',16,26,'O trabalhador trabalha para si mesmo, porque a sua boca o incita.'),
('acf','pv',16,27,'O homem ímpio cava o mal, e nos seus lábios há como que uma fogueira.'),
('acf','pv',16,28,'O homem perverso instiga a contenda, e o intrigante separa os maiores amigos.'),
('acf','pv',16,29,'O homem violento coage o seu próximo, e o faz deslizar por caminhos nada bons.'),
('acf','pv',16,30,'O que fecha os olhos para imaginar coisas ruins, ao cerrar os lábios pratica o mal.'),
('acf','pv',16,31,'Coroa de honra são as cãs, quando elas estão no caminho da justiça.'),
('acf','pv',16,32,'Melhor é o que tarda em irar-se do que o poderoso, e o que controla o seu ânimo do que aquele que toma uma cidade.'),
('acf','pv',16,33,'A sorte se lança no regaço, mas do Senhor procede toda a determinação.'),
('acf','pv',17,1,'É melhor um bocado seco, e com ele a tranqüilidade, do que a casa cheia de iguarias e com desavença.'),
('acf','pv',17,2,'O servo prudente dominará sobre o filho que faz envergonhar; e repartirá a herança entre os irmãos.'),
('acf','pv',17,3,'O crisol é para a prata, e o forno para o ouro; mas o Senhor é quem prova os corações.'),
('acf','pv',17,4,'O ímpio atenta para o lábio iníquo, o mentiroso inclina os ouvidos à língua maligna.'),
('acf','pv',17,5,'O que escarnece do pobre insulta ao seu Criador, o que se alegra da calamidade não ficará impune.'),
('acf','pv',17,6,'A coroa dos velhos são os filhos dos filhos; e a glória dos filhos são seus pais.'),
('acf','pv',17,7,'Não convém ao tolo a fala excelente; quanto menos ao príncipe, o lábio mentiroso.'),
('acf','pv',17,8,'O presente é, aos olhos dos que o recebem, como pedra preciosa; para onde quer que se volte servirá de proveito.'),
('acf','pv',17,9,'Aquele que encobre a transgressão busca a amizade, mas o que revolve o assunto separa os maiores amigos.'),
('acf','pv',17,10,'A repreensão penetra mais profundamente no prudente do que cem açoites no tolo.'),
('acf','pv',17,11,'Na verdade o rebelde não busca senão o mal; afinal, um mensageiro cruel será enviado contra ele.'),
('acf','pv',17,12,'Encontre-se o homem com a ursa roubada dos filhos, mas não com o louco na sua estultícia.'),
('acf','pv',17,13,'Quanto àquele que paga o bem com o mal, não se apartará o mal da sua casa.'),
('acf','pv',17,14,'Como o soltar das águas é o início da contenda, assim, antes que sejas envolvido afasta-te da questão.'),
('acf','pv',17,15,'O que justifica o ímpio, e o que condena o justo, tanto um como o outro são abomináveis ao Senhor.'),
('acf','pv',17,16,'De que serviria o preço na mão do tolo para comprar sabedoria, visto que não tem entendimento?'),
('acf','pv',17,17,'Em todo o tempo ama o amigo e para a hora da angústia nasce o irmão.'),
('acf','pv',17,18,'O homem falto de entendimento compromete-se, ficando por fiador na presença do seu amigo.'),
('acf','pv',17,19,'O que ama a transgressão ama a contenda; o que exalta a sua porta busca a ruína.'),
('acf','pv',17,20,'O perverso de coração jamais achará o bem; e o que tem a língua dobre vem a cair no mal.'),
('acf','pv',17,21,'O que gera um tolo para a sua tristeza o faz; e o pai do insensato não tem alegria.'),
('acf','pv',17,22,'O coração alegre é como o bom remédio, mas o espírito abatido seca até os ossos.'),
('acf','pv',17,23,'O ímpio toma presentes em secreto para perverter as veredas da justiça.'),
('acf','pv',17,24,'No rosto do entendido se vê a sabedoria, mas os olhos do tolo vagam pelas extremidades da terra.'),
('acf','pv',17,25,'O filho insensato é tristeza para seu pai, e amargura para aquela que o deu à luz.'),
('acf','pv',17,26,'Também não é bom punir o justo, nem tampouco ferir aos príncipes por eqüidade.'),
('acf','pv',17,27,'O que possui o conhecimento guarda as suas palavras, e o homem de entendimento é de precioso espírito.'),
('acf','pv',17,28,'Até o tolo, quando se cala, é reputado por sábio; e o que cerra os seus lábios é tido por entendido.'),
('acf','pv',18,1,'Busca satisfazer seu próprio desejo aquele que se isola; ele se insurge contra toda sabedoria.'),
('acf','pv',18,2,'O tolo não tem prazer na sabedoria, mas só em que se manifeste aquilo que agrada o seu coração.'),
('acf','pv',18,3,'Vindo o ímpio, vem também o desprezo, e com a ignomínia a vergonha.'),
('acf','pv',18,4,'Águas profundas são as palavras da boca do homem, e ribeiro transbordante é a fonte da sabedoria.'),
('acf','pv',18,5,'Não é bom favorecer o ímpio, e com isso, fazer o justo perder a questão.'),
('acf','pv',18,6,'Os lábios do tolo entram na contenda, e a sua boca brada por açoites.'),
('acf','pv',18,7,'A boca do tolo é a sua própria destruição, e os seus lábios um laço para a sua alma.'),
('acf','pv',18,8,'As palavras do mexeriqueiro são como doces bocados; elas descem ao íntimo do ventre.'),
('acf','pv',18,9,'O que é negligente na sua obra é também irmão do desperdiçador.'),
('acf','pv',18,10,'Torre forte é o nome do Senhor; a ela correrá o justo, e estará em alto refúgio.'),
('acf','pv',18,11,'Os bens do rico são a sua cidade forte, e como uma muralha na sua imaginação.'),
('acf','pv',18,12,'O coração do homem se exalta antes de ser abatido e diante da honra vai a humildade.'),
('acf','pv',18,13,'O que responde antes de ouvir comete estultícia que é para vergonha sua.'),
('acf','pv',18,14,'O espírito do homem susterá a sua enfermidade, mas ao espírito abatido, quem o suportará?'),
('acf','pv',18,15,'O coração do entendido adquire o conhecimento, e o ouvido dos sábios busca a sabedoria.'),
('acf','pv',18,16,'Com presentes o homem alarga o seu caminho e o eleva diante dos grandes.'),
('acf','pv',18,17,'O que pleiteia por algo, a princípio parece justo, porém vem o seu próximo e o examina.'),
('acf','pv',18,18,'A sorte faz cessar os pleitos, e faz separação entre os poderosos.'),
('acf','pv',18,19,'O irmão ofendido é mais difícil de conquistar do que uma cidade forte; e as contendas são como os ferrolhos de um palácio.'),
('acf','pv',18,20,'Do fruto da boca de cada um se fartará o seu ventre; dos renovos dos seus lábios ficará satisfeito.'),
('acf','pv',18,21,'A morte e a vida estão no poder da língua; e aquele que a ama comerá do seu fruto.'),
('acf','pv',18,22,'Aquele que encontra uma esposa, acha o bem, e alcança a benevolência do Senhor.'),
('acf','pv',18,23,'O pobre fala com rogos, mas o rico responde com dureza.'),
('acf','pv',18,24,'O homem de muitos amigos deve mostrar-se amigável, mas há um amigo mais chegado do que um irmão.'),
('acf','pv',19,1,'Melhor é o pobre que anda na sua integridade do que o perverso de lábios e tolo.'),
('acf','pv',19,2,'Assim como não é bom ficar a alma sem conhecimento, peca aquele que se apressa com seus pés.'),
('acf','pv',19,3,'A estultícia do homem perverterá o seu caminho, e o seu coração se irará contra o Senhor.'),
('acf','pv',19,4,'As riquezas granjeiam muitos amigos, mas ao pobre, o seu próprio amigo o deixa.'),
('acf','pv',19,5,'A falsa testemunha não ficará impune e o que respira mentiras não escapará.'),
('acf','pv',19,6,'Muitos se deixam acomodar pelos favores do príncipe, e cada um é amigo daquele que dá presentes.'),
('acf','pv',19,7,'Todos os irmãos do pobre o odeiam; quanto mais se afastarão dele os seus amigos! Corre após eles com palavras, que não servem de nada.'),
('acf','pv',19,8,'O que adquire entendimento ama a sua alma; o que cultiva a inteligência achará o bem.'),
('acf','pv',19,9,'A falsa testemunha não ficará impune; e o que profere mentiras perecerá.'),
('acf','pv',19,10,'Ao tolo não é certo gozar de deleites; quanto menos ao servo dominar sobre os príncipes!'),
('acf','pv',19,11,'A prudência do homem faz reter a sua ira, e é glória sua o passar por cima da transgressão.'),
('acf','pv',19,12,'Como o rugido do leão jovem é a indignação do rei, mas como o orvalho sobre a relva é a sua benevolência.'),
('acf','pv',19,13,'O filho insensato é uma desgraça para o pai, e um gotejar contínuo as contendas da mulher.'),
('acf','pv',19,14,'A casa e os bens são herança dos pais; porém do Senhor vem a esposa prudente.'),
('acf','pv',19,15,'A preguiça faz cair em profundo sono, e a alma indolente padecerá fome.'),
('acf','pv',19,16,'O que guardar o mandamento guardará a sua alma; porém o que desprezar os seus caminhos morrerá.'),
('acf','pv',19,17,'Ao Senhor empresta o que se compadece do pobre, ele lhe pagará o seu benefício.'),
('acf','pv',19,18,'Castiga o teu filho enquanto há esperança, mas não deixes que o teu ânimo se exalte até o matar.'),
('acf','pv',19,19,'O homem de grande indignação deve sofrer o dano; porque se tu o livrares ainda terás de tornar a fazê-lo.'),
('acf','pv',19,20,'Ouve o conselho, e recebe a correção, para que no fim sejas sábio.'),
('acf','pv',19,21,'Muitos propósitos há no coração do homem, porém o conselho do Senhor permanecerá.'),
('acf','pv',19,22,'O que o homem mais deseja é o que lhe faz bem; porém é melhor ser pobre do que mentiroso.'),
('acf','pv',19,23,'O temor do Senhor encaminha para a vida; aquele que o tem ficará satisfeito, e não o visitará mal nenhum.'),
('acf','pv',19,24,'O preguiçoso esconde a sua mão ao seio; e não tem disposição nem de torná-la à sua boca.'),
('acf','pv',19,25,'Açoita o escarnecedor, e o simples tomará aviso; repreende ao entendido, e aprenderá conhecimento.'),
('acf','pv',19,26,'O que aflige o seu pai, ou manda embora sua mãe, é filho que traz vergonha e desonra.'),
('acf','pv',19,27,'Filho meu, ouvindo a instrução, cessa de te desviares das palavras do conhecimento.'),
('acf','pv',19,28,'O ímpio escarnece do juízo, e a boca dos perversos devora a iniqüidade.'),
('acf','pv',19,29,'Preparados estão os juízos para os escarnecedores, e os açoites para as costas dos tolos.'),
('acf','pv',20,1,'O vinho é escarnecedor, a bebida forte alvoroçadora; e todo aquele que neles errar nunca será sábio.'),
('acf','pv',20,2,'Como o rugido do leão é o terror do rei; o que o provoca à ira peca contra a sua própria alma.'),
('acf','pv',20,3,'Honroso é para o homem desviar-se de questões, mas todo tolo é intrometido.'),
('acf','pv',20,4,'O preguiçoso não lavrará por causa do inverno, pelo que mendigará na sega, mas nada receberá.'),
('acf','pv',20,5,'Como as águas profundas é o conselho no coração do homem; mas o homem de inteligência o trará para fora.'),
('acf','pv',20,6,'A multidão dos homens apregoa a sua própria bondade, porém o homem fidedigno quem o achará?'),
('acf','pv',20,7,'O justo anda na sua sinceridade; bem-aventurados serão os seus filhos depois dele.'),
('acf','pv',20,8,'Assentando-se o rei no trono do juízo, com os seus olhos dissipa todo o mal.'),
('acf','pv',20,9,'Quem poderá dizer: Purifiquei o meu coração, limpo estou de meu pecado?'),
('acf','pv',20,10,'Dois pesos diferentes e duas espécies de medida são abominação ao Senhor, tanto um como outro.'),
('acf','pv',20,11,'Até a criança se dará a conhecer pelas suas ações, se a sua obra é pura e reta.'),
('acf','pv',20,12,'O ouvido que ouve, e o olho que vê, o Senhor os fez a ambos.'),
('acf','pv',20,13,'Não ames o sono, para que não empobreças; abre os teus olhos, e te fartarás de pão.'),
('acf','pv',20,14,'Nada vale, nada vale, dirá o comprador, mas, indo-se, então se gabará.'),
('acf','pv',20,15,'Há ouro e abundância de rubis, mas os lábios do conhecimento são jóia preciosa.'),
('acf','pv',20,16,'Ficando alguém por fiador de um estranho, tome-se-lhe a roupa; e por penhor àquele que se obriga pela mulher estranha.'),
('acf','pv',20,17,'Suave é ao homem o pão da mentira, mas depois a sua boca se encherá de cascalho.'),
('acf','pv',20,18,'Cada pensamento se confirma com conselho e com bons conselhos se faz a guerra.'),
('acf','pv',20,19,'O que anda tagarelando revela o segredo; não te intrometas com o que lisonjeia com os seus lábios.'),
('acf','pv',20,20,'O que amaldiçoa seu pai ou sua mãe, apagar-se-á a sua lâmpada em negras trevas.'),
('acf','pv',20,21,'A herança que no princípio é adquirida às pressas, no fim não será abençoada.'),
('acf','pv',20,22,'Não digas: Vingar-me-ei do mal; espera pelo Senhor, e ele te livrará.'),
('acf','pv',20,23,'Pesos diferentes são abomináveis ao Senhor, e balança enganosa não é boa.'),
('acf','pv',20,24,'Os passos do homem são dirigidos pelo Senhor; como, pois, entenderá o homem o seu caminho?'),
('acf','pv',20,25,'Laço é para o homem apropriar-se do que é santo, e só refletir depois de feitos os votos.'),
('acf','pv',20,26,'O rei sábio dispersa os ímpios e faz passar sobre eles a roda.'),
('acf','pv',20,27,'O espírito do homem é a lâmpada do Senhor, que esquadrinha todo o interior até o mais íntimo do ventre.'),
('acf','pv',20,28,'Benignidade e verdade guardam ao rei, e com benignidade sustém ele o seu trono.'),
('acf','pv',20,29,'A glória do jovem é a sua força; e a beleza dos velhos são as cãs.'),
('acf','pv',20,30,'Os vergões das feridas são a purificação dos maus, como também as pancadas que penetram até o mais íntimo do ventre.'),
('acf','pv',21,1,'Como ribeiros de águas assim é o coração do rei na mão do SENHOR, que o inclina a todo o seu querer.'),
('acf','pv',21,2,'Todo caminho do homem é reto aos seus olhos, mas o Senhor sonda os corações.'),
('acf','pv',21,3,'Fazer justiça e juízo é mais aceitável ao Senhor do que sacrifício.'),
('acf','pv',21,4,'Os olhos altivos, o coração orgulhoso e a lavoura dos ímpios é pecado.'),
('acf','pv',21,5,'Os pensamentos do diligente tendem só para a abundância, porém os de todo apressado, tão-somente para a pobreza.'),
('acf','pv',21,6,'Trabalhar com língua falsa para ajuntar tesouros é vaidade que conduz aqueles que buscam a morte.'),
('acf','pv',21,7,'As rapinas dos ímpios os destruirão, porquanto se recusam a fazer justiça.'),
('acf','pv',21,8,'O caminho do homem é todo perverso e estranho, porém a obra do homem puro é reta.'),
('acf','pv',21,9,'É melhor morar num canto de telhado do que ter como companheira em casa ampla uma mulher briguenta.'),
('acf','pv',21,10,'A alma do ímpio deseja o mal; o seu próximo não agrada aos seus olhos.'),
('acf','pv',21,11,'Quando o escarnecedor é castigado, o simples torna-se sábio; e o sábio quando é instruído recebe o conhecimento.'),
('acf','pv',21,12,'O justo considera com prudência a casa do ímpio; mas Deus destrói os ímpios por causa dos seus males.'),
('acf','pv',21,13,'O que tapa o seu ouvido ao clamor do pobre, ele mesmo também clamará e não será ouvido.'),
('acf','pv',21,14,'O presente dado em segredo aplaca a ira, e a dádiva no regaço põe fim à maior indignação.'),
('acf','pv',21,15,'O fazer justiça é alegria para o justo, mas destruição para os que praticam a iniqüidade.'),
('acf','pv',21,16,'O homem que anda desviado do caminho do entendimento, na congregação dos mortos repousará.'),
('acf','pv',21,17,'O que ama os prazeres padecerá necessidade; o que ama o vinho e o azeite nunca enriquecerá.'),
('acf','pv',21,18,'O resgate do justo é o ímpio; o do honrado é o perverso.'),
('acf','pv',21,19,'É melhor morar numa terra deserta do que com a mulher rixosa e irritadiça.'),
('acf','pv',21,20,'Tesouro desejável e azeite há na casa do sábio, mas o homem insensato os esgota.'),
('acf','pv',21,21,'O que segue a justiça e a beneficência achará a vida, a justiça e a honra.'),
('acf','pv',21,22,'O sábio escala a cidade do poderoso e derruba a força da sua confiança.'),
('acf','pv',21,23,'O que guarda a sua boca e a sua língua guarda a sua alma das angústias.'),
('acf','pv',21,24,'O soberbo e presumido, zombador é o seu nome, trata com indignação e soberba.'),
('acf','pv',21,25,'O desejo do preguiçoso o mata, porque as suas mãos recusam trabalhar.'),
('acf','pv',21,26,'O cobiçoso cobiça o dia todo, mas o justo dá, e nada retém.'),
('acf','pv',21,27,'O sacrifício dos ímpios já é abominação; quanto mais oferecendo-o com má intenção!'),
('acf','pv',21,28,'A falsa testemunha perecerá, porém o homem que dá ouvidos falará sempre.'),
('acf','pv',21,29,'O homem ímpio endurece o seu rosto; mas o reto considera o seu caminho.'),
('acf','pv',21,30,'Não há sabedoria, nem inteligência, nem conselho contra o Senhor.'),
('acf','pv',21,31,'Prepara-se o cavalo para o dia da batalha, porém do Senhor vem a vitória.'),
('acf','pv',22,1,'Vale mais ter um bom nome do que muitas riquezas; e o ser estimado é melhor do que a riqueza e o ouro.'),
('acf','pv',22,2,'O rico e o pobre se encontram; a todos o Senhor os fez.'),
('acf','pv',22,3,'O prudente prevê o mal, e esconde-se; mas os simples passam e acabam pagando.'),
('acf','pv',22,4,'O galardão da humildade e o temor do Senhor são riquezas, honra e vida.'),
('acf','pv',22,5,'Espinhos e laços há no caminho do perverso; o que guarda a sua alma retira-se para longe dele.'),
('acf','pv',22,6,'Educa a criança no caminho em que deve andar; e até quando envelhecer não se desviará dele.'),
('acf','pv',22,7,'O rico domina sobre os pobres e o que toma emprestado é servo do que empresta.'),
('acf','pv',22,8,'O que semear a perversidade segará males; e com a vara da sua própria indignação será extinto.'),
('acf','pv',22,9,'O que vê com bons olhos será abençoado, porque dá do seu pão ao pobre.'),
('acf','pv',22,10,'Lança fora o escarnecedor, e se irá a contenda; e acabará a questão e a vergonha.'),
('acf','pv',22,11,'O que ama a pureza de coração, e é amável de lábios, será amigo do rei.'),
('acf','pv',22,12,'Os olhos do Senhor conservam o conhecimento, mas as palavras do iníquo ele transtornará.'),
('acf','pv',22,13,'Diz o preguiçoso: Um leão está lá fora; serei morto no meio das ruas.'),
('acf','pv',22,14,'Cova profunda é a boca das mulheres estranhas; aquele contra quem o Senhor se irar, cairá nela.'),
('acf','pv',22,15,'A estultícia está ligada ao coração da criança, mas a vara da correção a afugentará dela.'),
('acf','pv',22,16,'O que oprime ao pobre para se engrandecer a si mesmo, ou o que dá ao rico, certamente empobrecerá.'),
('acf','pv',22,17,'Inclina o teu ouvido e ouve as palavras dos sábios, e aplica o teu coração ao meu conhecimento.'),
('acf','pv',22,18,'Porque te será agradável se as guardares no teu íntimo, se aplicares todas elas aos teus lábios.'),
('acf','pv',22,19,'Para que a tua confiança esteja no Senhor, faço-te sabê-las hoje, a ti mesmo.'),
('acf','pv',22,20,'Porventura não te escrevi excelentes coisas, acerca de todo conselho e conhecimento,'),
('acf','pv',22,21,'Para fazer-te saber a certeza das palavras da verdade, e assim possas responder palavras de verdade aos que te consultarem?'),
('acf','pv',22,22,'Não roubes ao pobre, porque é pobre, nem atropeles na porta o aflito;'),
('acf','pv',22,23,'Porque o Senhor defenderá a sua causa em juízo, e aos que os roubam ele lhes tirará a vida.'),
('acf','pv',22,24,'Não sejas companheiro do homem briguento nem andes com o colérico,'),
('acf','pv',22,25,'Para que não aprendas as suas veredas, e tomes um laço para a tua alma.'),
('acf','pv',22,26,'Não estejas entre os que se comprometem, e entre os que ficam por fiadores de dívidas,'),
('acf','pv',22,27,'Pois se não tens com que pagar, deixarias que te tirassem até a tua cama de debaixo de ti?'),
('acf','pv',22,28,'Não removas os antigos limites que teus pais fizeram.'),
('acf','pv',22,29,'Viste o homem diligente na sua obra? Perante reis será posto; não permanecerá entre os de posição inferior.'),
('acf','pv',23,1,'Quando te assentares a comer com um governador, atenta bem para o que é posto diante de ti,'),
('acf','pv',23,2,'E se és homem de grande apetite, põe uma faca à tua garganta.'),
('acf','pv',23,3,'Não cobices as suas iguarias porque são comidas enganosas.'),
('acf','pv',23,4,'Não te fatigues para enriqueceres; e não apliques nisso a tua sabedoria.'),
('acf','pv',23,5,'Porventura fixarás os teus olhos naquilo que não é nada? porque certamente criará asas e voará ao céu como a águia.'),
('acf','pv',23,6,'Não comas o pão daquele que tem o olhar maligno, nem cobices as suas iguarias gostosas.'),
('acf','pv',23,7,'Porque, como imaginou no seu coração, assim é ele. Come e bebe, te disse ele; porém o seu coração não está contigo.'),
('acf','pv',23,8,'Vomitarás o bocado que comeste, e perderás as tuas suaves palavras.'),
('acf','pv',23,9,'Não fales ao ouvido do tolo, porque desprezará a sabedoria das tuas palavras.'),
('acf','pv',23,10,'Não removas os limites antigos nem entres nos campos dos órfãos,'),
('acf','pv',23,11,'Porque o seu redentor é poderoso; e pleiteará a causa deles contra ti.'),
('acf','pv',23,12,'Aplica o teu coração à instrução e os teus ouvidos às palavras do conhecimento.'),
('acf','pv',23,13,'Não retires a disciplina da criança; pois se a fustigares com a vara, nem por isso morrerá.'),
('acf','pv',23,14,'Tu a fustigarás com a vara, e livrarás a sua alma do inferno.'),
('acf','pv',23,15,'Filho meu, se o teu coração for sábio, alegrar-se-á o meu coração, sim, o meu próprio.'),
('acf','pv',23,16,'E exultarão os meus rins, quando os teus lábios falarem coisas retas.'),
('acf','pv',23,17,'O teu coração não inveje os pecadores; antes permanece no temor do Senhor todo dia.'),
('acf','pv',23,18,'Porque certamente acabará bem; não será malograda a tua esperança.'),
('acf','pv',23,19,'Ouve tu, filho meu, e sê sábio, e dirige no caminho o teu coração.'),
('acf','pv',23,20,'Não estejas entre os beberrões de vinho, nem entre os comilões de carne.'),
('acf','pv',23,21,'Porque o beberrão e o comilão acabarão na pobreza; e a sonolência os faz vestir-se de trapos.'),
('acf','pv',23,22,'Ouve teu pai, que te gerou, e não desprezes tua mãe, quando vier a envelhecer.'),
('acf','pv',23,23,'Compra a verdade, e não a vendas; e também a sabedoria, a instrução e o entendimento.'),
('acf','pv',23,24,'Grandemente se regozijará o pai do justo, e o que gerar um sábio, se alegrará nele.'),
('acf','pv',23,25,'Alegrem-se teu pai e tua mãe, e regozije-se a que te gerou.'),
('acf','pv',23,26,'Dá-me, filho meu, o teu coração, e os teus olhos observem os meus caminhos.'),
('acf','pv',23,27,'Porque cova profunda é a prostituta, e poço estreito a estranha.'),
('acf','pv',23,28,'Pois ela, como um salteador, se põe à espreita, e multiplica entre os homens os iníquos.'),
('acf','pv',23,29,'Para quem são os ais? Para quem os pesares? Para quem as pelejas? Para quem as queixas? Para quem as feridas sem causa? E para quem os olhos vermelhos?'),
('acf','pv',23,30,'Para os que se demoram perto do vinho, para os que andam buscando vinho misturado.'),
('acf','pv',23,31,'Não olhes para o vinho quando se mostra vermelho, quando resplandece no copo e se escoa suavemente.'),
('acf','pv',23,32,'No fim, picará como a cobra, e como o basilisco morderá.'),
('acf','pv',23,33,'Os teus olhos olharão para as mulheres estranhas, e o teu coração falará perversidades.'),
('acf','pv',23,34,'E serás como o que se deita no meio do mar, e como o que jaz no topo do mastro.'),
('acf','pv',23,35,'E dirás: Espancaram-me e não me doeu; bateram-me e nem senti; quando despertarei? aí então beberei outra vez.'),
('acf','pv',24,1,'Não tenhas inveja dos homens malignos, nem desejes estar com eles.'),
('acf','pv',24,2,'Porque o seu coração medita a rapina, e os seus lábios falam a malícia.'),
('acf','pv',24,3,'Com a sabedoria se edifica a casa, e com o entendimento ela se estabelece;'),
('acf','pv',24,4,'E pelo conhecimento se encherão as câmaras com todos os bens preciosos e agradáveis.'),
('acf','pv',24,5,'O homem sábio é forte, e o homem de conhecimento consolida a força.'),
('acf','pv',24,6,'Com conselhos prudentes tu farás a guerra; e há vitória na multidão dos conselheiros.'),
('acf','pv',24,7,'A sabedoria é demasiadamente alta para o tolo, na porta não abrirá a sua boca.'),
('acf','pv',24,8,'Àquele que cuida em fazer mal, chamá-lo-ão de pessoa danosa.'),
('acf','pv',24,9,'O pensamento do tolo é pecado, e abominável aos homens é o escarnecedor.'),
('acf','pv',24,10,'Se te mostrares fraco no dia da angústia, é que a tua força é pequena.'),
('acf','pv',24,11,'Se tu deixares de livrar os que estão sendo levados para a morte, e aos que estão sendo levados para a matança;'),
('acf','pv',24,12,'Se disseres: Eis que não o sabemos; porventura não o considerará aquele que pondera os corações? Não o saberá aquele que atenta para a tua alma? Não dará ele ao homem conforme a sua obra?'),
('acf','pv',24,13,'Come mel, meu filho, porque é bom; o favo de mel é doce ao teu paladar.'),
('acf','pv',24,14,'Assim será para a tua alma o conhecimento da sabedoria; se a achares, haverá galardão para ti e não será cortada a tua esperança.'),
('acf','pv',24,15,'Não armes ciladas contra a habitação do justo, ó ímpio, nem assoles o seu lugar de repouso,'),
('acf','pv',24,16,'Porque sete vezes cairá o justo, e se levantará; mas os ímpios tropeçarão no mal.'),
('acf','pv',24,17,'Quando cair o teu inimigo, não te alegres, nem se regozije o teu coração quando ele tropeçar;'),
('acf','pv',24,18,'Para que, vendo-o o Senhor, seja isso mau aos seus olhos, e desvie dele a sua ira.'),
('acf','pv',24,19,'Não te indignes por causa dos malfeitores, nem tenhas inveja dos ímpios,'),
('acf','pv',24,20,'Porque o homem maligno não terá galardão, e a lâmpada dos ímpios se apagará.'),
('acf','pv',24,21,'Teme ao Senhor, filho meu, e ao rei, e não te ponhas com os que buscam mudanças,'),
('acf','pv',24,22,'Porque de repente se levantará a sua destruição, e a ruína de ambos, quem o sabe?'),
('acf','pv',24,23,'Também estes são provérbios dos sábios: Ter respeito a pessoas no julgamento não é bom.'),
('acf','pv',24,24,'O que disser ao ímpio: Justo és, os povos o amaldiçoarão, as nações o detestarão.'),
('acf','pv',24,25,'Mas para os que o repreenderem haverá delícias, e sobre eles virá a bênção do bem.'),
('acf','pv',24,26,'Beijados serão os lábios do que responde com palavras retas.'),
('acf','pv',24,27,'Prepara de fora a tua obra, e aparelha-a no campo, e então edifica a tua casa.'),
('acf','pv',24,28,'Não sejas testemunha sem causa contra o teu próximo; e não enganes com os teus lábios.'),
('acf','pv',24,29,'Não digas: Como ele me fez a mim, assim o farei eu a ele; pagarei a cada um segundo a sua obra.'),
('acf','pv',24,30,'Passei pelo campo do preguiçoso, e junto à vinha do homem falto de entendimento,'),
('acf','pv',24,31,'Eis que estava toda cheia de cardos, e a sua superfície coberta de urtiga, e o seu muro de pedras estava derrubado.'),
('acf','pv',24,32,'O que eu tenho visto, o guardarei no coração, e vendo-o recebi instrução.'),
('acf','pv',24,33,'Um pouco a dormir, um pouco a cochilar; outro pouco deitado de mãos cruzadas, para dormir,'),
('acf','pv',24,34,'Assim te sobrevirá a tua pobreza como um vagabundo, e a tua necessidade como um homem armado.'),
('acf','pv',25,1,'Também estes são provérbios de Salomão, os quais transcreveram os homens de Ezequias, rei de Judá.'),
('acf','pv',25,2,'A glória de Deus está nas coisas encobertas; mas a honra dos reis, está em descobri-las.'),
('acf','pv',25,3,'Os céus, pela altura, e a terra, pela profundidade, assim o coração dos reis é insondável.'),
('acf','pv',25,4,'Tira da prata as escórias, e sairá vaso para o fundidor;'),
('acf','pv',25,5,'Tira o ímpio da presença do rei, e o seu trono se firmará na justiça.'),
('acf','pv',25,6,'Não te glories na presença do rei, nem te ponhas no lugar dos grandes;'),
('acf','pv',25,7,'Porque melhor é que te digam: Sobe aqui; do que seres humilhado diante do príncipe que os teus olhos já viram.'),
('acf','pv',25,8,'Não te precipites em litigar, para que depois, ao fim, fiques sem ação, quando teu próximo te puser em apuros.'),
('acf','pv',25,9,'Pleiteia a tua causa com o teu próximo, e não reveles o segredo a outrem,'),
('acf','pv',25,10,'Para que não te desonre o que o ouvir, e a tua infâmia não se aparte de ti.'),
('acf','pv',25,11,'Como maçãs de ouro em salvas de prata, assim é a palavra dita a seu tempo.'),
('acf','pv',25,12,'Como pendentes de ouro e gargantilhas de ouro fino, assim é o sábio repreensor para o ouvido atento.'),
('acf','pv',25,13,'Como o frio da neve no tempo da sega, assim é o mensageiro fiel para com os que o enviam; porque refresca a alma dos seus senhores.'),
('acf','pv',25,14,'Como nuvens e ventos que não trazem chuva, assim é o homem que se gaba falsamente de dádivas.'),
('acf','pv',25,15,'Pela longanimidade se persuade o príncipe, e a língua branda amolece até os ossos.'),
('acf','pv',25,16,'Achaste mel? come só o que te basta; para que porventura não te fartes dele, e o venhas a vomitar.'),
('acf','pv',25,17,'Não ponhas muito os pés na casa do teu próximo; para que se não enfade de ti, e passe a te odiar.'),
('acf','pv',25,18,'Martelo, espada e flecha aguda é o homem que profere falso testemunho contra o seu próximo.'),
('acf','pv',25,19,'Como dente quebrado, e pé desconjuntado, é a confiança no desleal, no tempo da angústia.'),
('acf','pv',25,20,'O que canta canções para o coração aflito é como aquele que despe a roupa num dia de frio, ou como o vinagre sobre salitre.'),
('acf','pv',25,21,'Se o teu inimigo tiver fome, dá-lhe pão para comer; e se tiver sede, dá-lhe água para beber;'),
('acf','pv',25,22,'Porque assim lhe amontoarás brasas sobre a cabeça; e o Senhor to retribuirá.'),
('acf','pv',25,23,'O vento norte afugenta a chuva, e a face irada, a língua fingida.'),
('acf','pv',25,24,'Melhor é morar só num canto de telhado do que com a mulher briguenta numa casa ampla.'),
('acf','pv',25,25,'Como água fresca para a alma cansada, tais são as boas novas vindas da terra distante.'),
('acf','pv',25,26,'Como fonte turvada, e manancial poluído, assim é o justo que cede diante do ímpio.'),
('acf','pv',25,27,'Comer mel demais não é bom; assim, a busca da própria glória não é glória.'),
('acf','pv',25,28,'Como a cidade derrubada, sem muro, assim é o homem que não pode conter o seu espírito.'),
('acf','pv',26,1,'Como a neve no verão, e como a chuva na sega, assim não fica bem para o tolo a honra.'),
('acf','pv',26,2,'Como ao pássaro o vaguear, como à andorinha o voar, assim a maldição sem causa não virá.'),
('acf','pv',26,3,'O açoite é para o cavalo, o freio é para o jumento, e a vara é para as costas dos tolos.'),
('acf','pv',26,4,'Não respondas ao tolo segundo a sua estultícia; para que também não te faças semelhante a ele.'),
('acf','pv',26,5,'Responde ao tolo segundo a sua estultícia, para que não seja sábio aos seus próprios olhos.'),
('acf','pv',26,6,'Os pés corta, e o dano sorve, aquele que manda mensagem pela mão dum tolo.'),
('acf','pv',26,7,'Como as pernas do coxo, que pendem flácidas, assim é o provérbio na boca dos tolos.'),
('acf','pv',26,8,'Como o que arma a funda com pedra preciosa, assim é aquele que concede honra ao tolo.'),
('acf','pv',26,9,'Como o espinho que entra na mão do bêbado, assim é o provérbio na boca dos tolos.'),
('acf','pv',26,10,'O Poderoso, que formou todas as coisas, paga ao tolo, e recompensa ao transgressor.'),
('acf','pv',26,11,'Como o cão torna ao seu vômito, assim o tolo repete a sua estultícia.'),
('acf','pv',26,12,'Tens visto o homem que é sábio a seus próprios olhos? Pode-se esperar mais do tolo do que dele.'),
('acf','pv',26,13,'Diz o preguiçoso: Um leão está no caminho; um leão está nas ruas.'),
('acf','pv',26,14,'Como a porta gira nos seus gonzos, assim o preguiçoso na sua cama.'),
('acf','pv',26,15,'O preguiçoso esconde a sua mão ao seio; e cansa-se até de torná-la à sua boca.'),
('acf','pv',26,16,'Mais sábio é o preguiçoso a seus próprios olhos do que sete homens que respondem bem.'),
('acf','pv',26,17,'O que, passando, se põe em questão alheia, é como aquele que pega um cão pelas orelhas.'),
('acf','pv',26,18,'Como o louco que solta faíscas, flechas, e mortandades,'),
('acf','pv',26,19,'Assim é o homem que engana o seu próximo, e diz: Fiz isso por brincadeira.'),
('acf','pv',26,20,'Sem lenha, o fogo se apagará; e não havendo intrigante, cessará a contenda.'),
('acf','pv',26,21,'Como o carvão para as brasas, e a lenha para o fogo, assim é o homem contencioso para acender rixas.'),
('acf','pv',26,22,'As palavras do intrigante são como doces bocados; elas descem ao mais íntimo do ventre.'),
('acf','pv',26,23,'Como o caco de vaso coberto de escórias de prata, assim são os lábios ardentes com o coração maligno.'),
('acf','pv',26,24,'Aquele que odeia dissimula com seus lábios, mas no seu íntimo encobre o engano;'),
('acf','pv',26,25,'Quando te suplicar com voz suave não te fies nele, porque abriga sete abominações no seu coração,'),
('acf','pv',26,26,'Cujo ódio se encobre com engano, a sua maldade será exposta perante a congregação.'),
('acf','pv',26,27,'O que cava uma cova cairá nela; e o que revolve a pedra, esta voltará sobre ele.'),
('acf','pv',26,28,'A língua falsa odeia aos que ela fere, e a boca lisonjeira provoca a ruína.'),
('acf','pv',27,1,'Não presumas do dia de amanhã, porque não sabes o que ele trará.'),
('acf','pv',27,2,'Que um outro te louve, e não a tua própria boca; o estranho, e não os teus lábios.'),
('acf','pv',27,3,'A pedra é pesada, e a areia é espessa; porém a ira do insensato é mais pesada que ambas.'),
('acf','pv',27,4,'O furor é cruel e a ira impetuosa, mas quem poderá enfrentar a inveja?'),
('acf','pv',27,5,'Melhor é a repreensão franca do que o amor encoberto.'),
('acf','pv',27,6,'Leais são as feridas feitas pelo amigo, mas os beijos do inimigo são enganosos.'),
('acf','pv',27,7,'A alma farta pisa o favo de mel, mas para a alma faminta todo amargo é doce.'),
('acf','pv',27,8,'Qual a ave que vagueia longe do seu ninho, tal é o homem que anda vagueando longe da sua morada.'),
('acf','pv',27,9,'O óleo e o perfume alegram o coração; assim o faz a doçura do amigo pelo conselho cordial.'),
('acf','pv',27,10,'Não deixes o teu amigo, nem o amigo de teu pai; nem entres na casa de teu irmão no dia da tua adversidade; melhor é o vizinho perto do que o irmão longe.'),
('acf','pv',27,11,'Sê sábio, filho meu, e alegra o meu coração, para que tenha alguma coisa que responder àquele que me desprezar.'),
('acf','pv',27,12,'O avisado vê o mal e esconde-se; mas os simples passam e sofrem a pena.'),
('acf','pv',27,13,'Quando alguém fica por fiador do estranho, toma-lhe até a sua roupa, e por penhor àquele que se obriga pela mulher estranha.'),
('acf','pv',27,14,'O que, pela manhã de madrugada, abençoa o seu amigo em alta voz, lho será imputado por maldição.'),
('acf','pv',27,15,'O gotejar contínuo em dia de grande chuva, e a mulher contenciosa, uma e outra são semelhantes;'),
('acf','pv',27,16,'Tentar moderá-la será como deter o vento, ou como conter o óleo dentro da sua mão direita.'),
('acf','pv',27,17,'Como o ferro com ferro se aguça, assim o homem afia o rosto do seu amigo.'),
('acf','pv',27,18,'O que cuida da figueira comerá do seu fruto; e o que atenta para o seu senhor será honrado.'),
('acf','pv',27,19,'Como na água o rosto corresponde ao rosto, assim o coração do homem ao homem.'),
('acf','pv',27,20,'Como o inferno e a perdição nunca se fartam, assim os olhos do homem nunca se satisfazem.'),
('acf','pv',27,21,'Como o crisol é para a prata, e o forno para o ouro, assim o homem é provado pelos louvores.'),
('acf','pv',27,22,'Ainda que repreendas o tolo como quem bate o trigo com a mão de gral entre grãos pilados, não se apartará dele a sua estultícia.'),
('acf','pv',27,23,'Procura conhecer o estado das tuas ovelhas; põe o teu coração sobre os teus rebanhos,'),
('acf','pv',27,24,'Porque o tesouro não dura para sempre; e durará a coroa de geração em geração?'),
('acf','pv',27,25,'Quando brotar a erva, e aparecerem os renovos, e se juntarem as ervas dos montes,'),
('acf','pv',27,26,'Então os cordeiros serão para te vestires, e os bodes para o preço do campo;'),
('acf','pv',27,27,'E a abastança do leite das cabras para o teu sustento, para sustento da tua casa e para sustento das tuas servas.'),
('acf','pv',28,1,'Os ímpios fogem sem que haja ninguém a persegui-los; mas os justos são ousados como um leão.'),
('acf','pv',28,2,'Pela transgressão da terra muitos são os seus príncipes, mas por homem prudente e entendido a sua continuidade será prolongada.'),
('acf','pv',28,3,'O homem pobre que oprime os pobres é como a chuva impetuosa, que causa a falta de alimento.'),
('acf','pv',28,4,'Os que deixam a lei louvam o ímpio; porém os que guardam a lei contendem com eles.'),
('acf','pv',28,5,'Os homens maus não entendem o juízo, mas os que buscam ao Senhor entendem tudo.'),
('acf','pv',28,6,'Melhor é o pobre que anda na sua integridade do que o de caminhos perversos ainda que seja rico.'),
('acf','pv',28,7,'O que guarda a lei é filho sábio, mas o companheiro dos desregrados envergonha a seu pai.'),
('acf','pv',28,8,'O que aumenta os seus bens com usura e ganância ajunta-os para o que se compadece do pobre.'),
('acf','pv',28,9,'O que desvia os seus ouvidos de ouvir a lei, até a sua oração será abominável.'),
('acf','pv',28,10,'O que faz com que os retos errem por mau caminho, ele mesmo cairá na sua cova; mas os bons herdarão o bem.'),
('acf','pv',28,11,'O homem rico é sábio aos seus próprios olhos, mas o pobre que é entendido, o examina.'),
('acf','pv',28,12,'Quando os justos exultam, grande é a glória; mas quando os ímpios sobem, os homens se escondem.'),
('acf','pv',28,13,'O que encobre as suas transgressões nunca prosperará, mas o que as confessa e deixa, alcançará misericórdia.'),
('acf','pv',28,14,'Bem-aventurado o homem que continuamente teme; mas o que endurece o seu coração cairá no mal.'),
('acf','pv',28,15,'Como leão rugidor, e urso faminto, assim é o ímpio que domina sobre um povo pobre.'),
('acf','pv',28,16,'O príncipe falto de entendimento é também um grande opressor, mas o que odeia a avareza prolongará seus dias.'),
('acf','pv',28,17,'O homem carregado do sangue de qualquer pessoa fugirá até à cova; ninguém o detenha.'),
('acf','pv',28,18,'O que anda sinceramente salvar-se-á, mas o perverso em seus caminhos cairá logo.'),
('acf','pv',28,19,'O que lavrar a sua terra virá a fartar-se de pão, mas o que segue a ociosos se fartará de pobreza.'),
('acf','pv',28,20,'O homem fiel será coberto de bênçãos, mas o que se apressa a enriquecer não ficará impune.'),
('acf','pv',28,21,'Dar importância à aparência das pessoas não é bom, porque até por um bocado de pão um homem prevaricará.'),
('acf','pv',28,22,'O que quer enriquecer depressa é homem de olho maligno, porém não sabe que a pobreza há de vir sobre ele.'),
('acf','pv',28,23,'O que repreende o homem gozará depois mais amizade do que aquele que lisonjeia com a língua.'),
('acf','pv',28,24,'O que rouba a seu próprio pai, ou a sua mãe, e diz: Não é transgressão, companheiro é do homem destruidor.'),
('acf','pv',28,25,'O orgulhoso de coração levanta contendas, mas o que confia no Senhor prosperará.'),
('acf','pv',28,26,'O que confia no seu próprio coração é insensato, mas o que anda em sabedoria, será salvo.'),
('acf','pv',28,27,'O que dá ao pobre não terá necessidade, mas o que esconde os seus olhos terá muitas maldições.'),
('acf','pv',28,28,'Quando os ímpios se elevam, os homens andam se escondendo, mas quando perecem, os justos se multiplicam.'),
('acf','pv',29,1,'O Homem que muitas vezes repreendido endurece a cerviz, de repente será destruído sem que haja remédio.'),
('acf','pv',29,2,'Quando os justos se engrandecem, o povo se alegra, mas quando o ímpio domina, o povo geme.'),
('acf','pv',29,3,'O homem que ama a sabedoria alegra a seu pai, mas o companheiro de prostitutas desperdiça os bens.'),
('acf','pv',29,4,'O rei com juízo sustém a terra, mas o amigo de peitas a transtorna.'),
('acf','pv',29,5,'O homem que lisonjeia o seu próximo arma uma rede aos seus passos.'),
('acf','pv',29,6,'Na transgressão do homem mau há laço, mas o justo jubila e se alegra.'),
('acf','pv',29,7,'O justo se informa da causa dos pobres, mas o ímpio nem sequer toma conhecimento.'),
('acf','pv',29,8,'Os homens escarnecedores alvoroçam a cidade, mas os sábios desviam a ira.'),
('acf','pv',29,9,'O homem sábio que pleiteia com o tolo, quer se zangue, quer se ria, não terá descanso.'),
('acf','pv',29,10,'Os homens sanguinários odeiam ao sincero, mas os justos procuram o seu bem.'),
('acf','pv',29,11,'O tolo revela todo o seu pensamento, mas o sábio o guarda até o fim.'),
('acf','pv',29,12,'O governador que dá atenção às palavras mentirosas, achará que todos os seus servos são ímpios.'),
('acf','pv',29,13,'O pobre e o usurário se encontram; o Senhor ilumina os olhos de ambos.'),
('acf','pv',29,14,'O rei que julga os pobres conforme a verdade firmará o seu trono para sempre.'),
('acf','pv',29,15,'A vara e a repreensão dão sabedoria, mas a criança entregue a si mesma, envergonha a sua mãe.'),
('acf','pv',29,16,'Quando os ímpios se multiplicam, multiplicam-se as transgressões, mas os justos verão a sua queda.'),
('acf','pv',29,17,'Castiga o teu filho, e te dará descanso; e dará delícias à tua alma.'),
('acf','pv',29,18,'Não havendo profecia, o povo perece; porém o que guarda a lei, esse é bem-aventurado.'),
('acf','pv',29,19,'O servo não se emendará com palavras, porque, ainda que entenda, todavia não atenderá.'),
('acf','pv',29,20,'Tens visto um homem precipitado no falar? Maior esperança há para um tolo do que para ele.'),
('acf','pv',29,21,'Quando alguém cria o seu servo com mimos desde a meninice, por fim ele tornar-se-á seu filho.'),
('acf','pv',29,22,'O homem irascível levanta contendas; e o furioso multiplica as transgressões.'),
('acf','pv',29,23,'A soberba do homem o abaterá, mas a honra sustentará o humilde de espírito.'),
('acf','pv',29,24,'O que tem parte com o ladrão odeia a sua própria alma; ouve maldições, e não o denuncia.'),
('acf','pv',29,25,'O temor do homem armará laços, mas o que confia no Senhor será posto em alto retiro.'),
('acf','pv',29,26,'Muitos buscam o favor do poderoso, mas o juízo de cada um vem do Senhor.'),
('acf','pv',29,27,'Abominação é, para os justos, o homem iníquo; mas abominação é, para o iníquo, o de retos caminhos.'),
('acf','pv',30,1,'Palavras de Agur, filho de Jaque, o masaíta, que proferiu este homem a Itiel, a Itiel e a Ucal:'),
('acf','pv',30,2,'Na verdade eu sou o mais bruto dos homens, nem mesmo tenho o conhecimento de homem.'),
('acf','pv',30,3,'Nem aprendi a sabedoria, nem tenho o conhecimento do santo.'),
('acf','pv',30,4,'Quem subiu ao céu e desceu? Quem encerrou os ventos nos seus punhos? Quem amarrou as águas numa roupa? Quem estabeleceu todas as extremidades da terra? Qual é o seu nome? E qual é o nome de seu filho, se é que o sabes?'),
('acf','pv',30,5,'Toda a Palavra de Deus é pura; escudo é para os que confiam nele.'),
('acf','pv',30,6,'Nada acrescentes às suas palavras, para que não te repreenda e sejas achado mentiroso.'),
('acf','pv',30,7,'Duas coisas te pedi; não mas negues, antes que morra:'),
('acf','pv',30,8,'Afasta de mim a vaidade e a palavra mentirosa; não me dês nem a pobreza nem a riqueza; mantém-me do pão da minha porção de costume;'),
('acf','pv',30,9,'Para que, porventura, estando farto não te negue, e venha a dizer: Quem é o Senhor? ou que, empobrecendo, não venha a furtar, e tome o nome de Deus em vão.'),
('acf','pv',30,10,'Não acuses o servo diante de seu senhor, para que não te amaldiçoe e tu fiques o culpado.'),
('acf','pv',30,11,'Há uma geração que amaldiçoa a seu pai, e que não bendiz a sua mãe.'),
('acf','pv',30,12,'Há uma geração que é pura aos seus próprios olhos, mas que nunca foi lavada da sua imundícia.'),
('acf','pv',30,13,'Há uma geração cujos olhos são altivos, e as suas pálpebras são sempre levantadas.'),
('acf','pv',30,14,'Há uma geração cujos dentes são espadas, e cujas queixadas são facas, para consumirem da terra os aflitos, e os necessitados dentre os homens.'),
('acf','pv',30,15,'A sanguessuga tem duas filhas: Dá e Dá. Estas três coisas nunca se fartam; e com a quarta, nunca dizem: Basta!'),
('acf','pv',30,16,'A sepultura; a madre estéril; a terra que não se farta de água; e o fogo; nunca dizem: Basta!'),
('acf','pv',30,17,'Os olhos que zombam do pai, ou desprezam a obediência à mãe, corvos do ribeiro os arrancarão e os filhotes da águia os comerão.'),
('acf','pv',30,18,'Estas três coisas me maravilham; e quatro há que não conheço:'),
('acf','pv',30,19,'O caminho da águia no ar; o caminho da cobra na penha; o caminho do navio no meio do mar; e o caminho do homem com uma virgem.'),
('acf','pv',30,20,'O caminho da mulher adúltera é assim: ela come, depois limpa a sua boca e diz: Não fiz nada de mal!'),
('acf','pv',30,21,'Por três coisas se alvoroça a terra; e por quatro que não pode suportar:'),
('acf','pv',30,22,'Pelo servo, quando reina; e pelo tolo, quando vive na fartura;'),
('acf','pv',30,23,'Pela mulher odiosa, quando é casada; e pela serva, quando fica herdeira da sua senhora.'),
('acf','pv',30,24,'Estas quatro coisas são das menores da terra, porém bem providas de sabedoria:'),
('acf','pv',30,25,'As formigas não são um povo forte; todavia no verão preparam a sua comida;'),
('acf','pv',30,26,'Os coelhos são um povo débil; e contudo, põem a sua casa na rocha;'),
('acf','pv',30,27,'Os gafanhotos não têm rei; e contudo todos saem, e em bandos se repartem;'),
('acf','pv',30,28,'A aranha se pendura com as mãos, e está nos palácios dos reis.'),
('acf','pv',30,29,'Estes três têm um bom andar, e quatro passeiam airosamente;'),
('acf','pv',30,30,'O leão, o mais forte entre os animais, que não foge de nada;'),
('acf','pv',30,31,'O galgo; o bode também; e o rei a quem não se pode resistir.'),
('acf','pv',30,32,'Se procedeste loucamente, exaltando-te, e se planejaste o mal, leva a mão à boca;'),
('acf','pv',30,33,'Porque o mexer do leite produz manteiga, o espremer do nariz produz sangue; assim o forçar da ira produz contenda.'),
('acf','pv',31,1,'Palavras do rei Lemuel, a profecia que lhe ensinou a sua mãe.'),
('acf','pv',31,2,'Como, filho meu? e como, filho do meu ventre? e como, filho dos meus votos?'),
('acf','pv',31,3,'Não dês às mulheres a tua força, nem os teus caminhos ao que destrói os reis.'),
('acf','pv',31,4,'Não é próprio dos reis, ó Lemuel, não é próprio dos reis beber vinho, nem dos príncipes o desejar bebida forte;'),
('acf','pv',31,5,'Para que bebendo, se esqueçam da lei, e pervertam o direito de todos os aflitos.'),
('acf','pv',31,6,'Dai bebida forte ao que está prestes a perecer, e o vinho aos amargurados de espírito.'),
('acf','pv',31,7,'Que beba, e esqueça da sua pobreza, e da sua miséria não se lembre mais.'),
('acf','pv',31,8,'Abre a tua boca a favor do mudo, pela causa de todos que são designados à destruição.'),
('acf','pv',31,9,'Abre a tua boca; julga retamente; e faze justiça aos pobres e aos necessitados.'),
('acf','pv',31,10,'Mulher virtuosa quem a achará? O seu valor muito excede ao de rubis.'),
('acf','pv',31,11,'O coração do seu marido está nela confiado; assim ele não necessitará de despojo.'),
('acf','pv',31,12,'Ela só lhe faz bem, e não mal, todos os dias da sua vida.'),
('acf','pv',31,13,'Busca lã e linho, e trabalha de boa vontade com suas mãos.'),
('acf','pv',31,14,'Como o navio mercante, ela traz de longe o seu pão.'),
('acf','pv',31,15,'Levanta-se, mesmo à noite, para dar de comer aos da casa, e distribuir a tarefa das servas.'),
('acf','pv',31,16,'Examina uma propriedade e adquire-a; planta uma vinha com o fruto de suas mãos.'),
('acf','pv',31,17,'Cinge os seus lombos de força, e fortalece os seus braços.'),
('acf','pv',31,18,'Vê que é boa a sua mercadoria; e a sua lâmpada não se apaga de noite.'),
('acf','pv',31,19,'Estende as suas mãos ao fuso, e suas mãos pegam na roca.'),
('acf','pv',31,20,'Abre a sua mão ao pobre, e estende as suas mãos ao necessitado.'),
('acf','pv',31,21,'Não teme a neve na sua casa, porque toda a sua família está vestida de escarlata.'),
('acf','pv',31,22,'Faz para si cobertas de tapeçaria; seu vestido é de seda e de púrpura.'),
('acf','pv',31,23,'Seu marido é conhecido nas portas, e assenta-se entre os anciãos da terra.'),
('acf','pv',31,24,'Faz panos de linho fino e vende-os, e entrega cintos aos mercadores.'),
('acf','pv',31,25,'A força e a honra são seu vestido, e se alegrará com o dia futuro.'),
('acf','pv',31,26,'Abre a sua boca com sabedoria, e a lei da beneficência está na sua língua.'),
('acf','pv',31,27,'Está atenta ao andamento da casa, e não come o pão da preguiça.'),
('acf','pv',31,28,'Levantam-se seus filhos e chamam-na bem-aventurada; seu marido também, e ele a louva.'),
('acf','pv',31,29,'Muitas filhas têm procedido virtuosamente, mas tu és, de todas, a mais excelente!'),
('acf','pv',31,30,'Enganosa é a beleza e vã a formosura, mas a mulher que teme ao Senhor, essa sim será louvada.'),
('acf','pv',31,31,'Dai-lhe do fruto das suas mãos, e deixe o seu próprio trabalho louvá-la nas portas.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ec',1,1,'Palavras do pregador, filho de Davi, rei em Jerusalém.'),
('acf','ec',1,2,'Vaidade de vaidades, diz o pregador, vaidade de vaidades! Tudo é vaidade.'),
('acf','ec',1,3,'Que proveito tem o homem, de todo o seu trabalho, que faz debaixo do sol?'),
('acf','ec',1,4,'Uma geração vai, e outra geração vem; mas a terra para sempre permanece.'),
('acf','ec',1,5,'Nasce o sol, e o sol se põe, e apressa-se e volta ao seu lugar de onde nasceu.'),
('acf','ec',1,6,'O vento vai para o sul, e faz o seu giro para o norte; continuamente vai girando o vento, e volta fazendo os seus circuitos.'),
('acf','ec',1,7,'Todos os rios vão para o mar, e contudo o mar não se enche; ao lugar para onde os rios vão, para ali tornam eles a correr.'),
('acf','ec',1,8,'Todas as coisas são trabalhosas; o homem não o pode exprimir; os olhos não se fartam de ver, nem os ouvidos se enchem de ouvir.'),
('acf','ec',1,9,'O que foi, isso é o que há de ser; e o que se fez, isso se fará; de modo que nada há de novo debaixo do sol.'),
('acf','ec',1,10,'Há alguma coisa de que se possa dizer: Vê, isto é novo? Já foi nos séculos passados, que foram antes de nós.'),
('acf','ec',1,11,'Já não há lembrança das coisas que precederam, e das coisas que hão de ser também delas não haverá lembrança, entre os que hão de vir depois.'),
('acf','ec',1,12,'Eu, o pregador, fui rei sobre Israel em Jerusalém.'),
('acf','ec',1,13,'E apliquei o meu coração a esquadrinhar, e a informar-me com sabedoria de tudo quanto sucede debaixo do céu; esta enfadonha ocupação deu Deus aos filhos dos homens, para nela os exercitar.'),
('acf','ec',1,14,'Atentei para todas as obras que se fazem debaixo do sol, e eis que tudo era vaidade e aflição de espírito.'),
('acf','ec',1,15,'Aquilo que é torto não se pode endireitar; aquilo que falta não se pode calcular.'),
('acf','ec',1,16,'Falei eu com o meu coração, dizendo: Eis que eu me engrandeci, e sobrepujei em sabedoria a todos os que houve antes de mim em Jerusalém; e o meu coração contemplou abundantemente a sabedoria e o conhecimento.'),
('acf','ec',1,17,'E apliquei o meu coração a conhecer a sabedoria e a conhecer os desvarios e as loucuras, e vim a saber que também isto era aflição de espírito.'),
('acf','ec',1,18,'Porque na muita sabedoria há muito enfado; e o que aumenta em conhecimento, aumenta em dor.'),
('acf','ec',2,1,'Disse eu no meu coração: Ora vem, eu te provarei com alegria; portanto goza o prazer; mas eis que também isso era vaidade.'),
('acf','ec',2,2,'Ao riso disse: Está doido; e da alegria: De que serve esta?'),
('acf','ec',2,3,'Busquei no meu coração como estimular com vinho a minha carne (regendo porém o meu coração com sabedoria), e entregar-me à loucura, até ver o que seria melhor que os filhos dos homens fizessem debaixo do céu durante o número dos dias de sua vida.'),
('acf','ec',2,4,'Fiz para mim obras magníficas; edifiquei para mim casas; plantei para mim vinhas.'),
('acf','ec',2,5,'Fiz para mim hortas e jardins, e plantei neles árvores de toda a espécie de fruto.'),
('acf','ec',2,6,'Fiz para mim tanques de águas, para regar com eles o bosque em que reverdeciam as árvores.'),
('acf','ec',2,7,'Adquiri servos e servas, e tive servos nascidos em casa; também tive grandes possessões de gados e ovelhas, mais do que todos os que houve antes de mim em Jerusalém.'),
('acf','ec',2,8,'Amontoei também para mim prata e ouro, e tesouros dos reis e das províncias; provi-me de cantores e cantoras, e das delícias dos filhos dos homens; e de instrumentos de música de toda a espécie.'),
('acf','ec',2,9,'E fui engrandecido, e aumentei mais do que todos os que houve antes de mim em Jerusalém; perseverou também comigo a minha sabedoria.'),
('acf','ec',2,10,'E tudo quanto desejaram os meus olhos não lhes neguei, nem privei o meu coração de alegria alguma; mas o meu coração se alegrou por todo o meu trabalho, e esta foi a minha porção de todo o meu trabalho.'),
('acf','ec',2,11,'E olhei eu para todas as obras que fizeram as minhas mãos, como também para o trabalho que eu, trabalhando, tinha feito, e eis que tudo era vaidade e aflição de espírito, e que proveito nenhum havia debaixo do sol.'),
('acf','ec',2,12,'Então passei a contemplar a sabedoria, e a loucura e a estultícia. Pois que fará o homem que seguir ao rei? O mesmo que outros já fizeram.'),
('acf','ec',2,13,'Então vi eu que a sabedoria é mais excelente do que a estultícia, quanto a luz é mais excelente do que as trevas.'),
('acf','ec',2,14,'Os olhos do homem sábio estão na sua cabeça, mas o louco anda em trevas; então também entendi eu que o mesmo lhes sucede a ambos.'),
('acf','ec',2,15,'Assim eu disse no meu coração: Como acontece ao tolo, assim me sucederá a mim; por que então busquei eu mais a sabedoria? Então disse no meu coração que também isto era vaidade.'),
('acf','ec',2,16,'Porque nunca haverá mais lembrança do sábio do que do tolo; porquanto de tudo, nos dias futuros, total esquecimento haverá. E como morre o sábio, assim morre o tolo!'),
('acf','ec',2,17,'Por isso odiei esta vida, porque a obra que se faz debaixo do sol me era penosa; sim, tudo é vaidade e aflição de espírito.'),
('acf','ec',2,18,'Também eu odiei todo o meu trabalho, que realizei debaixo do sol, visto que eu havia de deixá-lo ao homem que viesse depois de mim.'),
('acf','ec',2,19,'E quem sabe se será sábio ou tolo? Todavia, se assenhoreará de todo o meu trabalho que realizei e em que me houve sabiamente debaixo do sol; também isto é vaidade.'),
('acf','ec',2,20,'Então eu me volvi e entreguei o meu coração ao desespero no tocante ao trabalho, o qual realizei debaixo do sol.'),
('acf','ec',2,21,'Porque há homem cujo trabalho é feito com sabedoria, conhecimento, e destreza; contudo deixará o seu trabalho como porção de quem nele não trabalhou; também isto é vaidade e grande mal.'),
('acf','ec',2,22,'Porque, que mais tem o homem de todo o seu trabalho, e da aflição do seu coração, em que ele anda trabalhando debaixo do sol?'),
('acf','ec',2,23,'Porque todos os seus dias são dores, e a sua ocupação é aflição; até de noite não descansa o seu coração; também isto é vaidade.'),
('acf','ec',2,24,'Não há nada melhor para o homem do que comer e beber, e fazer com que sua alma goze do bem do seu trabalho. Também vi que isto vem da mão de Deus.'),
('acf','ec',2,25,'Pois quem pode comer, ou quem pode gozar melhor do que eu?'),
('acf','ec',2,26,'Porque ao homem que é bom diante dele, dá Deus sabedoria e conhecimento e alegria; mas ao pecador dá trabalho, para que ele ajunte, e amontoe, para dá-lo ao que é bom perante Deus. Também isto é vaidade e aflição de espírito.'),
('acf','ec',3,1,'Tudo tem o seu tempo determinado, e há tempo para todo o propósito debaixo do céu.'),
('acf','ec',3,2,'Há tempo de nascer, e tempo de morrer; tempo de plantar, e tempo de arrancar o que se plantou;'),
('acf','ec',3,3,'Tempo de matar, e tempo de curar; tempo de derrubar, e tempo de edificar;'),
('acf','ec',3,4,'Tempo de chorar, e tempo de rir; tempo de prantear, e tempo de dançar;'),
('acf','ec',3,5,'Tempo de espalhar pedras, e tempo de ajuntar pedras; tempo de abraçar, e tempo de afastar-se de abraçar;'),
('acf','ec',3,6,'Tempo de buscar, e tempo de perder; tempo de guardar, e tempo de lançar fora;'),
('acf','ec',3,7,'Tempo de rasgar, e tempo de coser; tempo de estar calado, e tempo de falar;'),
('acf','ec',3,8,'Tempo de amar, e tempo de odiar; tempo de guerra, e tempo de paz.'),
('acf','ec',3,9,'Que proveito tem o trabalhador naquilo em que trabalha?'),
('acf','ec',3,10,'Tenho visto o trabalho que Deus deu aos filhos dos homens, para com ele os exercitar.'),
('acf','ec',3,11,'Tudo fez formoso em seu tempo; também pôs o mundo no coração do homem, sem que este possa descobrir a obra que Deus fez desde o princípio até ao fim.'),
('acf','ec',3,12,'Já tenho entendido que não há coisa melhor para eles do que alegrar-se e fazer bem na sua vida;'),
('acf','ec',3,13,'E também que todo o homem coma e beba, e goze do bem de todo o seu trabalho; isto é um dom de Deus.'),
('acf','ec',3,14,'Eu sei que tudo quanto Deus faz durará eternamente; nada se lhe deve acrescentar, e nada se lhe deve tirar; e isto faz Deus para que haja temor diante dele.'),
('acf','ec',3,15,'O que é, já foi; e o que há de ser, também já foi; e Deus pede conta do que passou.'),
('acf','ec',3,16,'Vi mais debaixo do sol que no lugar do juízo havia impiedade, e no lugar da justiça havia iniqüidade.'),
('acf','ec',3,17,'Eu disse no meu coração: Deus julgará o justo e o ímpio; porque há um tempo para todo o propósito e para toda a obra.'),
('acf','ec',3,18,'Disse eu no meu coração, quanto a condição dos filhos dos homens, que Deus os provaria, para que assim pudessem ver que são em si mesmos como os animais.'),
('acf','ec',3,19,'Porque o que sucede aos filhos dos homens, isso mesmo também sucede aos animais, e lhes sucede a mesma coisa; como morre um, assim morre o outro; e todos têm o mesmo fôlego, e a vantagem dos homens sobre os animais não é nenhuma, porque todos são vaidade.'),
('acf','ec',3,20,'Todos vão para um lugar; todos foram feitos do pó, e todos voltarão ao pó.'),
('acf','ec',3,21,'Quem sabe que o fôlego do homem vai para cima, e que o fôlego dos animais vai para baixo da terra?'),
('acf','ec',3,22,'Assim que tenho visto que não há coisa melhor do que alegrar-se o homem nas suas obras, porque essa é a sua porção; pois quem o fará voltar para ver o que será depois dele?'),
('acf','ec',4,1,'Depois voltei-me, e atentei para todas as opressões que se fazem debaixo do sol; e eis que vi as lágrimas dos que foram oprimidos e dos que não têm consolador, e a força estava do lado dos seus opressores; mas eles não tinham consolador.'),
('acf','ec',4,2,'Por isso eu louvei os que já morreram, mais do que os que vivem ainda.'),
('acf','ec',4,3,'E melhor que uns e outros é aquele que ainda não é; que não viu as más obras que se fazem debaixo do sol.'),
('acf','ec',4,4,'Também vi eu que todo o trabalho, e toda a destreza em obras, traz ao homem a inveja do seu próximo. Também isto é vaidade e aflição de espírito.'),
('acf','ec',4,5,'O tolo cruza as suas mãos, e come a sua própria carne.'),
('acf','ec',4,6,'Melhor é a mão cheia com descanso do que ambas as mãos cheias com trabalho, e aflição de espírito.'),
('acf','ec',4,7,'Outra vez me voltei, e vi vaidade debaixo do sol.'),
('acf','ec',4,8,'Há um que é só, e não tem ninguém, nem tampouco filho nem irmão; e contudo não cessa do seu trabalho, e também seus olhos não se satisfazem com riqueza; nem diz: Para quem trabalho eu, privando a minha alma do bem? Também isto é vaidade e enfadonha ocupação.'),
('acf','ec',4,9,'Melhor é serem dois do que um, porque têm melhor paga do seu trabalho.'),
('acf','ec',4,10,'Porque se um cair, o outro levanta o seu companheiro; mas ai do que estiver só; pois, caindo, não haverá outro que o levante.'),
('acf','ec',4,11,'Também, se dois dormirem juntos, eles se aquentarão; mas um só, como se aquentará?'),
('acf','ec',4,12,'E, se alguém prevalecer contra um, os dois lhe resistirão; e o cordão de três dobras não se quebra tão depressa.'),
('acf','ec',4,13,'Melhor é a criança pobre e sábia do que o rei velho e insensato, que não se deixa mais admoestar.'),
('acf','ec',4,14,'Porque um sai do cárcere para reinar; enquanto outro, que nasceu em seu reino, torna-se pobre.'),
('acf','ec',4,15,'Vi a todos os viventes andarem debaixo do sol com a criança, a sucessora, que ficará no seu lugar.'),
('acf','ec',4,16,'Não tem fim todo o povo que foi antes dele; tampouco os que lhe sucederem se alegrarão dele. Na verdade que também isto é vaidade e aflição de espírito.'),
('acf','ec',5,1,'Guarda o teu pé, quando entrares na casa de Deus; porque chegar-se para ouvir é melhor do que oferecer sacrifícios de tolos, pois não sabem que fazem mal.'),
('acf','ec',5,2,'Não te precipites com a tua boca, nem o teu coração se apresse a pronunciar palavra alguma diante de Deus; porque Deus está nos céus, e tu estás sobre a terra; assim sejam poucas as tuas palavras.'),
('acf','ec',5,3,'Porque, da muita ocupação vêm os sonhos, e a voz do tolo da multidão das palavras.'),
('acf','ec',5,4,'Quando a Deus fizeres algum voto, não tardes em cumpri-lo; porque não se agrada de tolos; o que votares, paga-o.'),
('acf','ec',5,5,'Melhor é que não votes do que votares e não cumprires.'),
('acf','ec',5,6,'Não consintas que a tua boca faça pecar a tua carne, nem digas diante do anjo que foi erro; por que razão se iraria Deus contra a tua voz, e destruiria a obra das tuas mãos?'),
('acf','ec',5,7,'Porque, como na multidão dos sonhos há vaidades, assim também nas muitas palavras; mas tu teme a Deus.'),
('acf','ec',5,8,'Se vires em alguma província opressão do pobre, e violência do direito e da justiça, não te admires de tal procedimento; pois quem está altamente colocado tem superior que o vigia; e há mais altos do que eles.'),
('acf','ec',5,9,'O proveito da terra é para todos; até o rei se serve do campo.'),
('acf','ec',5,10,'Quem amar o dinheiro jamais dele se fartará; e quem amar a abundância nunca se fartará da renda; também isto é vaidade.'),
('acf','ec',5,11,'Onde os bens se multiplicam, ali se multiplicam também os que deles comem; que mais proveito, pois, têm os seus donos do que os ver com os seus olhos?'),
('acf','ec',5,12,'Doce é o sono do trabalhador, quer coma pouco quer muito; mas a fartura do rico não o deixa dormir.'),
('acf','ec',5,13,'Há um grave mal que vi debaixo do sol, e atrai enfermidades: as riquezas que os seus donos guardam para o seu próprio dano;'),
('acf','ec',5,14,'Porque as mesmas riquezas se perdem por qualquer má ventura, e havendo algum filho nada lhe fica na sua mão.'),
('acf','ec',5,15,'Como saiu do ventre de sua mãe, assim nu tornará, indo-se como veio; e nada tomará do seu trabalho, que possa levar na sua mão.'),
('acf','ec',5,16,'Assim que também isto é um grave mal que, justamente como veio, assim há de ir; e que proveito lhe vem de trabalhar para o vento,'),
('acf','ec',5,17,'E de haver comido todos os seus dias nas trevas, e de haver padecido muito enfado, e enfermidade, e furor?'),
('acf','ec',5,18,'Eis aqui o que eu vi, uma boa e bela coisa: comer e beber, e gozar cada um do bem de todo o seu trabalho, em que trabalhou debaixo do sol, todos os dias de vida que Deus lhe deu, porque esta é a sua porção.'),
('acf','ec',5,19,'E a todo o homem, a quem Deus deu riquezas e bens, e lhe deu poder para delas comer e tomar a sua porção, e gozar do seu trabalho, isto é dom de Deus.'),
('acf','ec',5,20,'Porque não se lembrará muito dos dias da sua vida; porquanto Deus lhe enche de alegria o seu coração.'),
('acf','ec',6,1,'Há um mal que tenho visto debaixo do sol, e é mui freqüente entre os homens:'),
('acf','ec',6,2,'Um homem a quem Deus deu riquezas, bens e honra, e nada lhe falta de tudo quanto a sua alma deseja, e Deus não lhe dá poder para daí comer, antes o estranho lho come; também isto é vaidade e má enfermidade.'),
('acf','ec',6,3,'Se o homem gerar cem filhos, e viver muitos anos, e os dias dos seus anos forem muitos, e se a sua alma não se fartar do bem, e além disso não tiver sepultura, digo que um aborto é melhor do que ele.'),
('acf','ec',6,4,'Porquanto debalde veio, e em trevas se vai, e de trevas se cobre o seu nome.'),
('acf','ec',6,5,'E ainda que nunca viu o sol, nem conheceu nada, mais descanso tem este do que aquele.'),
('acf','ec',6,6,'E, ainda que vivesse duas vezes mil anos e não gozasse o bem, não vão todos para um mesmo lugar?'),
('acf','ec',6,7,'Todo o trabalho do homem é para a sua boca, e contudo nunca se satisfaz o seu apetite.'),
('acf','ec',6,8,'Porque, que mais tem o sábio do que o tolo? E que mais tem o pobre que sabe andar perante os vivos?'),
('acf','ec',6,9,'Melhor é a vista dos olhos do que o vaguear da cobiça; também isto é vaidade e aflição de espírito.'),
('acf','ec',6,10,'Seja qualquer o que for, já o seu nome foi nomeado, e sabe-se que é homem, e que não pode contender com o que é mais forte do que ele.'),
('acf','ec',6,11,'Na verdade que há muitas coisas que multiplicam a vaidade; que mais tem o homem de melhor?'),
('acf','ec',6,12,'Pois, quem sabe o que é bom nesta vida para o homem, por todos os dias da sua vida de vaidade, os quais gasta como sombra? Quem declarará ao homem o que será depois dele debaixo do sol?'),
('acf','ec',7,1,'Melhor é a boa fama do que o melhor ungüento, e o dia da morte do que o dia do nascimento de alguém.'),
('acf','ec',7,2,'Melhor é ir à casa onde há luto do que ir à casa onde há banquete, porque naquela está o fim de todos os homens, e os vivos o aplicam ao seu coração.'),
('acf','ec',7,3,'Melhor é a mágoa do que o riso, porque com a tristeza do rosto se faz melhor o coração.'),
('acf','ec',7,4,'O coração dos sábios está na casa do luto, mas o coração dos tolos na casa da alegria.'),
('acf','ec',7,5,'Melhor é ouvir a repreensão do sábio, do que ouvir alguém a canção do tolo.'),
('acf','ec',7,6,'Porque qual o crepitar dos espinhos debaixo de uma panela, tal é o riso do tolo; também isto é vaidade.'),
('acf','ec',7,7,'Verdadeiramente que a opressão faria endoidecer até ao sábio, e o suborno corrompe o coração.'),
('acf','ec',7,8,'Melhor é o fim das coisas do que o princípio delas; melhor é o paciente de espírito do que o altivo de espírito.'),
('acf','ec',7,9,'Não te apresses no teu espírito a irar-te, porque a ira repousa no íntimo dos tolos.'),
('acf','ec',7,10,'Nunca digas: Por que foram os dias passados melhores do que estes? Porque não provém da sabedoria esta pergunta.'),
('acf','ec',7,11,'Tão boa é a sabedoria como a herança, e dela tiram proveito os que vêem o sol.'),
('acf','ec',7,12,'Porque a sabedoria serve de defesa, como de defesa serve o dinheiro; mas a excelência do conhecimento é que a sabedoria dá vida ao seu possuidor.'),
('acf','ec',7,13,'Atenta para a obra de Deus; porque quem poderá endireitar o que ele fez torto?'),
('acf','ec',7,14,'No dia da prosperidade goza do bem, mas no dia da adversidade considera; porque também Deus fez a este em oposição àquele, para que o homem nada descubra do que há de vir depois dele.'),
('acf','ec',7,15,'Tudo isto vi nos dias da minha vaidade: há justo que perece na sua justiça, e há ímpio que prolonga os seus dias na sua maldade.'),
('acf','ec',7,16,'Não sejas demasiadamente justo, nem demasiadamente sábio; por que te destruirias a ti mesmo?'),
('acf','ec',7,17,'Não sejas demasiadamente ímpio, nem sejas louco; por que morrerias fora de teu tempo?'),
('acf','ec',7,18,'Bom é que retenhas isto, e também daquilo não retires a tua mão; porque quem teme a Deus escapa de tudo isso.'),
('acf','ec',7,19,'A sabedoria fortalece ao sábio, mais do que dez poderosos que haja na cidade.'),
('acf','ec',7,20,'Na verdade que não há homem justo sobre a terra, que faça o bem, e nunca peque.'),
('acf','ec',7,21,'Tampouco apliques o teu coração a todas as palavras que se disserem, para que não venhas a ouvir o teu servo amaldiçoar-te.'),
('acf','ec',7,22,'Porque o teu coração também já confessou que muitas vezes tu amaldiçoaste a outros.'),
('acf','ec',7,23,'Tudo isto provei-o pela sabedoria; eu disse: Sabedoria adquirirei; mas ela ainda estava longe de mim.'),
('acf','ec',7,24,'O que já sucedeu é remoto e profundíssimo; quem o achará?'),
('acf','ec',7,25,'Eu apliquei o meu coração para saber, e inquirir, e buscar a sabedoria e a razão das coisas, e para conhecer que a impiedade é insensatez e que a estultícia é loucura.'),
('acf','ec',7,26,'E eu achei uma coisa mais amarga do que a morte, a mulher cujo coração são redes e laços, e cujas mãos são ataduras; quem for bom diante de Deus escapará dela, mas o pecador virá a ser preso por ela.'),
('acf','ec',7,27,'Vedes aqui, isto achei, diz o pregador, conferindo uma coisa com a outra para achar a razão delas;'),
('acf','ec',7,28,'A qual ainda busca a minha alma, porém ainda não a achei; um homem entre mil achei eu, mas uma mulher entre todas estas não achei.'),
('acf','ec',7,29,'Eis aqui, o que tão-somente achei: que Deus fez ao homem reto, porém eles buscaram muitas astúcias.'),
('acf','ec',8,1,'Quem é como o sábio? E quem sabe a interpretação das coisas? A sabedoria do homem faz brilhar o seu rosto, e a dureza do seu rosto se muda.'),
('acf','ec',8,2,'Eu digo: Observa o mandamento do rei, e isso em consideração ao juramento que fizeste a Deus.'),
('acf','ec',8,3,'Não te apresses a sair da presença dele, nem persistas em alguma coisa má, porque ele faz tudo o que quer.'),
('acf','ec',8,4,'Porque a palavra do rei tem poder; e quem lhe dirá: Que fazes?'),
('acf','ec',8,5,'Quem guardar o mandamento não experimentará nenhum mal; e o coração do sábio discernirá o tempo e o juízo.'),
('acf','ec',8,6,'Porque para todo o propósito há seu tempo e juízo; porquanto a miséria do homem pesa sobre ele.'),
('acf','ec',8,7,'Porque não sabe o que há de suceder, e quando há de ser, quem lho dará a entender?'),
('acf','ec',8,8,'Nenhum homem há que tenha domínio sobre o espírito, para o reter; nem tampouco tem ele poder sobre o dia da morte; como também não há licença nesta peleja; nem tampouco a impiedade livrará aos ímpios.'),
('acf','ec',8,9,'Tudo isto vi quando apliquei o meu coração a toda a obra que se faz debaixo do sol; tempo há em que um homem tem domínio sobre outro homem, para desgraça sua.'),
('acf','ec',8,10,'Assim também vi os ímpios, quando os sepultavam; e eles entravam, e saíam do lugar santo; e foram esquecidos na cidade, em que assim fizeram; também isso é vaidade.'),
('acf','ec',8,11,'Porquanto não se executa logo o juízo sobre a má obra, por isso o coração dos filhos dos homens está inteiramente disposto para fazer o mal.'),
('acf','ec',8,12,'Ainda que o pecador faça o mal cem vezes, e os dias se lhe prolonguem, contudo eu sei com certeza que bem sucede aos que temem a Deus, aos que temem diante dele.'),
('acf','ec',8,13,'Porém o ímpio não irá bem, e ele não prolongará os seus dias, que são como a sombra; porque ele não teme diante de Deus.'),
('acf','ec',8,14,'Ainda há outra vaidade que se faz sobre a terra: que há justos a quem sucede segundo as obras dos ímpios, e há ímpios a quem sucede segundo as obras dos justos. Digo que também isto é vaidade.'),
('acf','ec',8,15,'Então louvei eu a alegria, porquanto para o homem nada há melhor debaixo do sol do que comer, beber e alegrar-se; porque isso o acompanhará no seu trabalho nos dias da sua vida que Deus lhe dá debaixo do sol.'),
('acf','ec',8,16,'Aplicando eu o meu coração a conhecer a sabedoria, e a ver o trabalho que há sobre a terra (que nem de dia nem de noite vê o homem sono nos seus olhos);'),
('acf','ec',8,17,'Então vi toda a obra de Deus, que o homem não pode perceber, a obra que se faz debaixo do sol; por mais que trabalhe o homem para a descobrir, não a achará; e, ainda que diga o sábio que a conhece, nem por isso a poderá compreender.'),
('acf','ec',9,1,'Deveras todas estas coisas considerei no meu coração, para declarar tudo isto: que os justos, e os sábios, e as suas obras, estão nas mãos de Deus, e também o homem não conhece nem o amor nem o ódio; tudo passa perante ele.'),
('acf','ec',9,2,'Tudo sucede igualmente a todos; o mesmo sucede ao justo e ao ímpio, ao bom e ao puro, como ao impuro; assim ao que sacrifica como ao que não sacrifica; assim ao bom como ao pecador; ao que jura como ao que teme o juramento.'),
('acf','ec',9,3,'Este é o mal que há entre tudo quanto se faz debaixo do sol; a todos sucede o mesmo; e que também o coração dos filhos dos homens está cheio de maldade, e que há desvarios no seu coração enquanto vivem, e depois se vão aos mortos.'),
('acf','ec',9,4,'Ora, para aquele que está entre os vivos há esperança (porque melhor é o cão vivo do que o leão morto).'),
('acf','ec',9,5,'Porque os vivos sabem que hão de morrer, mas os mortos não sabem coisa nenhuma, nem tampouco terão eles recompensa, mas a sua memória fica entregue ao esquecimento.'),
('acf','ec',9,6,'Também o seu amor, o seu ódio, e a sua inveja já pereceram, e já não têm parte alguma para sempre, em coisa alguma do que se faz debaixo do sol.'),
('acf','ec',9,7,'Vai, pois, come com alegria o teu pão e bebe com coração contente o teu vinho, pois já Deus se agrada das tuas obras.'),
('acf','ec',9,8,'Em todo o tempo sejam alvas as tuas roupas, e nunca falte o óleo sobre a tua cabeça.'),
('acf','ec',9,9,'Goza a vida com a mulher que amas, todos os dias da tua vida vã, os quais Deus te deu debaixo do sol, todos os dias da tua vaidade; porque esta é a tua porção nesta vida, e no teu trabalho, que tu fizeste debaixo do sol.'),
('acf','ec',9,10,'Tudo quanto te vier à mão para fazer, faze-o conforme as tuas forças, porque na sepultura, para onde tu vais, não há obra nem projeto, nem conhecimento, nem sabedoria alguma.'),
('acf','ec',9,11,'Voltei-me, e vi debaixo do sol que não é dos ligeiros a carreira, nem dos fortes a batalha, nem tampouco dos sábios o pão, nem tampouco dos prudentes as riquezas, nem tampouco dos entendidos o favor, mas que o tempo e a oportunidade ocorrem a todos.'),
('acf','ec',9,12,'que também o homem não sabe o seu tempo; assim como os peixes que se pescam com a rede maligna, e como os passarinhos que se prendem com o laço, assim se enlaçam também os filhos dos homens no mau tempo, quando cai de repente sobre eles.'),
('acf','ec',9,13,'Também vi esta sabedoria debaixo do sol, que para mim foi grande:'),
('acf','ec',9,14,'Houve uma pequena cidade em que havia poucos homens, e veio contra ela um grande rei, e a cercou e levantou contra ela grandes baluartes;'),
('acf','ec',9,15,'E encontrou-se nela um sábio pobre, que livrou aquela cidade pela sua sabedoria, e ninguém se lembrava daquele pobre homem.'),
('acf','ec',9,16,'Então disse eu: Melhor é a sabedoria do que a força, ainda que a sabedoria do pobre foi desprezada, e as suas palavras não foram ouvidas.'),
('acf','ec',9,17,'As palavras dos sábios devem em silêncio ser ouvidas, mais do que o clamor do que domina entre os tolos.'),
('acf','ec',9,18,'Melhor é a sabedoria do que as armas de guerra, porém um só pecador destrói muitos bens.'),
('acf','ec',10,1,'Assim como as moscas mortas fazem exalar mau cheiro e inutilizar o ungüento do perfumador, assim é, para o famoso em sabedoria e em honra, um pouco de estultícia.'),
('acf','ec',10,2,'O coração do sábio está à sua direita, mas o coração do tolo está à sua esquerda.'),
('acf','ec',10,3,'E, até quando o tolo vai pelo caminho, falta-lhe o seu entendimento e diz a todos que é tolo.'),
('acf','ec',10,4,'Levantando-se contra ti o espírito do governador, não deixes o teu lugar, porque a submissão é um remédio que aplaca grandes ofensas.'),
('acf','ec',10,5,'Ainda há um mal que vi debaixo do sol, como o erro que procede do governador.'),
('acf','ec',10,6,'A estultícia está posta em grandes alturas, mas os ricos estão assentados em lugar baixo.'),
('acf','ec',10,7,'Vi os servos a cavalo, e os príncipes andando sobre a terra como servos.'),
('acf','ec',10,8,'Quem abrir uma cova, nela cairá, e quem romper um muro, uma cobra o morderá.'),
('acf','ec',10,9,'Aquele que transporta pedras, será maltratado por elas, e o que racha lenha expõe-se ao perigo.'),
('acf','ec',10,10,'Se estiver embotado o ferro, e não se afiar o corte, então se deve redobrar a força; mas a sabedoria é excelente para dirigir.'),
('acf','ec',10,11,'Seguramente a serpente morderá antes de estar encantada, e o falador não é melhor.'),
('acf','ec',10,12,'Nas palavras da boca do sábio há favor, porém os lábios do tolo o devoram.'),
('acf','ec',10,13,'O princípio das palavras da sua boca é a estultícia, e o fim do seu falar um desvario péssimo.'),
('acf','ec',10,14,'O tolo multiplica as palavras, porém, o homem não sabe o que será; e quem lhe fará saber o que será depois dele?'),
('acf','ec',10,15,'O trabalho dos tolos a cada um deles fatiga, porque não sabem como ir à cidade.'),
('acf','ec',10,16,'Ai de ti, ó terra, quando teu rei é uma criança, e cujos príncipes comem de manhã.'),
('acf','ec',10,17,'Bem-aventurada tu, ó terra, quando teu rei é filho dos nobres, e teus príncipes comem a tempo, para se fortalecerem, e não para bebedice.'),
('acf','ec',10,18,'Por muita preguiça se enfraquece o teto, e pela frouxidão das mãos a casa goteja.'),
('acf','ec',10,19,'Para rir se fazem banquetes, e o vinho produz alegria, e por tudo o dinheiro responde.'),
('acf','ec',10,20,'Nem ainda no teu pensamento amaldiçoes ao rei, nem tampouco no mais interior da tua recâmara amaldiçoes ao rico; porque as aves dos céus levariam a voz, e os que têm asas dariam notícia do assunto.'),
('acf','ec',11,1,'Lança o teu pão sobre as águas, porque depois de muitos dias o acharás.'),
('acf','ec',11,2,'Reparte com sete, e ainda até com oito, porque não sabes que mal haverá sobre a terra.'),
('acf','ec',11,3,'Estando as nuvens cheias, derramam a chuva sobre a terra, e caindo a árvore para o sul, ou para o norte, no lugar em que a árvore cair ali ficará.'),
('acf','ec',11,4,'Quem observa o vento, nunca semeará, e o que olha para as nuvens nunca segará.'),
('acf','ec',11,5,'Assim como tu não sabes qual o caminho do vento, nem como se formam os ossos no ventre da mulher grávida, assim também não sabes as obras de Deus, que faz todas as coisas.'),
('acf','ec',11,6,'Pela manhã semeia a tua semente, e à tarde não retires a tua mão, porque tu não sabes qual prosperará, se esta, se aquela, ou se ambas serão igualmente boas.'),
('acf','ec',11,7,'Certamente suave é a luz, e agradável é aos olhos ver o sol.'),
('acf','ec',11,8,'Porém, se o homem viver muitos anos, e em todos eles se alegrar, também se deve lembrar dos dias das trevas, porque hão de ser muitos. Tudo quanto sucede é vaidade.'),
('acf','ec',11,9,'Alegra-te, jovem, na tua mocidade, e recreie-se o teu coração nos dias da tua mocidade, e anda pelos caminhos do teu coração, e pela vista dos teus olhos; sabe, porém, que por todas estas coisas te trará Deus a juízo.'),
('acf','ec',11,10,'Afasta, pois, a ira do teu coração, e remove da tua carne o mal, porque a adolescência e a juventude são vaidade.'),
('acf','ec',12,1,'Lembra-te também do teu Criador nos dias da tua mocidade, antes que venham os maus dias, e cheguem os anos dos quais venhas a dizer: Não tenho neles contentamento;'),
('acf','ec',12,2,'Antes que se escureçam o sol, e a luz, e a lua, e as estrelas, e tornem a vir as nuvens depois da chuva;'),
('acf','ec',12,3,'No dia em que tremerem os guardas da casa, e se encurvarem os homens fortes, e cessarem os moedores, por já serem poucos, e se escurecerem os que olham pelas janelas;'),
('acf','ec',12,4,'E as portas da rua se fecharem por causa do baixo ruído da moedura, e se levantar à voz das aves, e todas as filhas da música se abaterem.'),
('acf','ec',12,5,'Como também quando temerem o que é alto, e houver espantos no caminho, e florescer a amendoeira, e o gafanhoto for um peso, e perecer o apetite; porque o homem se vai à sua casa eterna, e os pranteadore andarão rodeando pela praça;'),
('acf','ec',12,6,'Antes que se rompa o cordão de prata, e se quebre o copo de ouro, e se despedace o cântaro junto à fonte, e se quebre a roda junto ao poço,'),
('acf','ec',12,7,'E o pó volte à terra, como o era, e o espírito volte a Deus, que o deu.'),
('acf','ec',12,8,'Vaidade de vaidades, diz o pregador, tudo é vaidade.'),
('acf','ec',12,9,'E, quanto mais sábio foi o pregador, tanto mais ensinou ao povo sabedoria; e atentando, e esquadrinhando, compôs muitos provérbios.'),
('acf','ec',12,10,'Procurou o pregador achar palavras agradáveis; e escreveu-as com retidão, palavras de verdade.'),
('acf','ec',12,11,'As palavras dos sábios são como aguilhões, e como pregos, bem fixados pelos mestres das assembléias, que nos foram dadas pelo único Pastor.'),
('acf','ec',12,12,'E, demais disto, filho meu, atenta: não há limite para fazer livros, e o muito estudar é enfado da carne.'),
('acf','ec',12,13,'De tudo o que se tem ouvido, o fim é: Teme a Deus, e guarda os seus mandamentos; porque isto é o dever de todo o homem.'),
('acf','ec',12,14,'Porque Deus há de trazer a juízo toda a obra, e até tudo o que está encoberto, quer seja bom, quer seja mau.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ct',1,1,'cântico dos cânticos, que é de Salomão.'),
('acf','ct',1,2,'Beije-me ele com os beijos da sua boca; porque melhor é o teu amor do que o vinho.'),
('acf','ct',1,3,'Suave é o aroma dos teus ungüentos; como o ungüento derramado é o teu nome; por isso as virgens te amam.'),
('acf','ct',1,4,'Leva-me tu; correremos após ti. O rei me introduziu nas suas câmaras; em ti nos regozijaremos e nos alegraremos; do teu amor nos lembraremos, mais do que do vinho; os retos te amam.'),
('acf','ct',1,5,'Eu sou morena, porém formosa, ó filhas de Jerusalém, como as tendas de Quedar, como as cortinas de Salomão.'),
('acf','ct',1,6,'Não olheis para o eu ser morena, porque o sol resplandeceu sobre mim; os filhos de minha mãe indignaram-se contra mim, puseram-me por guarda das vinhas; a minha vinha, porém, não guardei.'),
('acf','ct',1,7,'Dize-me, ó tu, a quem ama a minha alma: Onde apascentas o teu rebanho, onde o fazes descansar ao meio-dia; pois por que razão seria eu como a que anda errante junto aos rebanhos de teus companheiros?'),
('acf','ct',1,8,'Se tu não o sabes, ó mais formosa entre as mulheres, sai-te pelas pisadas do rebanho, e apascenta as tuas cabras junto às moradas dos pastores.'),
('acf','ct',1,9,'Às éguas dos carros de Faraó te comparo, ó meu amor.'),
('acf','ct',1,10,'Formosas são as tuas faces entre os teus enfeites, o teu pescoço com os colares.'),
('acf','ct',1,11,'Enfeites de ouro te faremos, com incrustações de prata.'),
('acf','ct',1,12,'Enquanto o rei está assentado à sua mesa, o meu nardo exala o seu perfume.'),
('acf','ct',1,13,'O meu amado é para mim como um ramalhete de mirra, posto entre os meus seios.'),
('acf','ct',1,14,'Como um ramalhete de hena nas vinhas de En-Gedi, é para mim o meu amado.'),
('acf','ct',1,15,'Eis que és formosa, ó meu amor, eis que és formosa; os teus olhos são como os das pombas.'),
('acf','ct',1,16,'Eis que és formoso, ó amado meu, e também amável; o nosso leito é verde.'),
('acf','ct',1,17,'As traves da nossa casa são de cedro, as nossas varandas de cipreste.'),
('acf','ct',2,1,'Eu sou a rosa de Sarom, o lírio dos vales.'),
('acf','ct',2,2,'Qual o lírio entre os espinhos, tal é meu amor entre as filhas.'),
('acf','ct',2,3,'Qual a macieira entre as árvores do bosque, tal é o meu amado entre os filhos;desejo muito a sua sombra, e debaixo dela me assento;e o seu fruto é doce ao meu paladar.'),
('acf','ct',2,4,'Levou-me à casa do banquete, e o seu estandarte sobre mim era o amor.'),
('acf','ct',2,5,'Sustentai-me com passas, confortai-me com maçãs, porque desfaleço de amor.'),
('acf','ct',2,6,'A sua mão esquerda esteja debaixo da minha cabeça, e a sua mão direita me abrace.'),
('acf','ct',2,7,'Conjuro-vos, ó filhas de Jerusalém, pelas gazelas e cervas do campo, que não acordeis nem desperteis o meu amor, até que queira.'),
('acf','ct',2,8,'Esta é a voz do meu amado; ei-lo aí, que já vem saltando sobre os montes, pulando sobre os outeiros.'),
('acf','ct',2,9,'O meu amado é semelhante ao gamo, ou ao filho do veado; eis que está detrás da nossa parede, olhando pelas janelas, espreitando pelas grades.'),
('acf','ct',2,10,'O meu amado fala e me diz: Levanta-te, meu amor, formosa minha, e vem.'),
('acf','ct',2,11,'Porque eis que passou o inverno; a chuva cessou, e se foi;'),
('acf','ct',2,12,'Aparecem as flores na terra, o tempo de cantar chega, e a voz da rola ouve-se em nossa terra.'),
('acf','ct',2,13,'A figueira já deu os seus figos verdes, e as vides em flor exalam o seu aroma; levanta-te, meu amor, formosa minha, e vem.'),
('acf','ct',2,14,'Pomba minha, que andas pelas fendas das penhas, no oculto das ladeiras, mostra-me a tua face, faze-me ouvir a tua voz, porque a tua voz é doce, e a tua face graciosa.'),
('acf','ct',2,15,'Apanhai-nos as raposas, as raposinhas, que fazem mal às vinhas, porque as nossas vinhas estão em flor.'),
('acf','ct',2,16,'O meu amado é meu, e eu sou dele; ele apascenta o seu rebanho entre os lírios.'),
('acf','ct',2,17,'Até que refresque o dia, e fujam as sombras, volta, amado meu; faze-te semelhante ao gamo ou ao filho dos veados sobre os montes de Beter.'),
('acf','ct',3,1,'De noite, em minha cama, busquei aquele a quem ama a minha alma; busquei-o, e não o achei.'),
('acf','ct',3,2,'Levantar-me-ei, pois, e rodearei a cidade;pelas ruas e pelas praças buscarei aquele a quem ama a minha alma;busquei-o, e não o achei.'),
('acf','ct',3,3,'Acharam-me os guardas, que rondavam pela cidade;eu lhes perguntei: Vistes aquele a quem ama a minha alma?'),
('acf','ct',3,4,'Apartando-me eu um pouco deles, logo achei aquele a quem ama a minha alma; agarrei-me a ele, e não o larguei, até que o introduzi em casa de minha mãe, na câmara daquela que me gerou.'),
('acf','ct',3,5,'Conjuro-vos, ó filhas de Jerusalém, pelas gazelas e cervas do campo, que não acordeis, nem desperteis o meu amor, até que queira.'),
('acf','ct',3,6,'Quem é esta que sobe do deserto, como colunas de fumaça, perfumada de mirra, de incenso, e de todos os pós dos mercadores?'),
('acf','ct',3,7,'Eis que é a liteira de Salomão; sessenta valentes estão ao redor dela, dos valentes de Israel;'),
('acf','ct',3,8,'Todos armados de espadas, destros na guerra; cada um com a sua espada à cinta por causa dos temores noturnos.'),
('acf','ct',3,9,'O rei Salomão fez para si uma carruagem de madeira do Líbano.'),
('acf','ct',3,10,'Fez-lhe as colunas de prata, o estrado de ouro, o assento de púrpura, o interior revestido com amor, pelas filhas de Jerusalém.'),
('acf','ct',3,11,'Saí, ó filhas de Sião, e contemplai ao rei Salomão com a coroa com que o coroou sua mãe no dia do seu desposório e no dia do júbilo do seu coração.'),
('acf','ct',4,1,'Eis que és formosa, meu amor, eis que és formosa; os teus olhos são como os das pombas entre as tuas tranças; o teu cabelo é como o rebanho de cabras que pastam no monte de Gileade.'),
('acf','ct',4,2,'Os teus dentes são como o rebanho das ovelhas tosquiadas, que sobem do lavadouro, e das quais todas produzem gêmeos, e nenhuma há estéril entre elas.'),
('acf','ct',4,3,'Os teus lábios são como um fio de escarlate, e o teu falar é agradável; a tua fronte é qual um pedaço de romã entre os teus cabelos.'),
('acf','ct',4,4,'O teu pescoço é como a torre de Davi, edificada para pendurar armas; mil escudos pendem dela, todos broquéis de poderosos.'),
('acf','ct',4,5,'Os teus dois seios são como dois filhos gêmeos da gazela, que se apascentam entre os lírios.'),
('acf','ct',4,6,'Até que refresque o dia, e fujam as sombras, irei ao monte da mirra, e ao outeiro do incenso.'),
('acf','ct',4,7,'Tu és toda formosa, meu amor, e em ti não há mancha.'),
('acf','ct',4,8,'Vem comigo do Líbano, ó minha esposa, vem comigo do Líbano; olha desde o cume de Amana, desde o cume de Senir e de Hermom, desde os covis dos leões, desde os montes dos leopardos.'),
('acf','ct',4,9,'Enlevaste-me o coração, minha irmã, minha esposa; enlevaste-me o coração com um dos teus olhares, com um colar do teu pescoço.'),
('acf','ct',4,10,'Que belos são os teus amores, minha irmã, esposa minha! Quanto melhor é o teu amor do que o vinho! E o aroma dos teus ungüentos do que o de todas as especiarias!'),
('acf','ct',4,11,'Favos de mel manam dos teus lábios, minha esposa! Mel e leite estão debaixo da tua língua, e o cheiro dos teus vestidos é como o cheiro do Líbano.'),
('acf','ct',4,12,'Jardim fechado és tu, minha irmã, esposa minha, manancial fechado, fonte selada.'),
('acf','ct',4,13,'Os teus renovos são um pomar de romãs, com frutos excelentes, o cipreste com o nardo.'),
('acf','ct',4,14,'O nardo, e o açafrão, o cálamo, e a canela, com toda a sorte de árvores de incenso, a mirra e aloés, com todas as principais especiarias.'),
('acf','ct',4,15,'És a fonte dos jardins, poço das águas vivas, que correm do Líbano!'),
('acf','ct',4,16,'Levanta-te, vento norte, e vem tu, vento sul; assopra no meu jardim, para que destilem os seus aromas. Ah! entre o meu amado no jardim, e coma os seus frutos excelentes!'),
('acf','ct',5,1,'Já entrei no meu jardim, minha irmã, minha esposa; colhi a minha mirra com a minha especiaria, comi o meu favo com o meu mel, bebi o meu vinho com o meu leite; comei, amigos, bebei abundantemente, ó amados.'),
('acf','ct',5,2,'Eu dormia, mas o meu coração velava; e eis a voz do meu amado que está batendo: abre-me, minha irmã, meu amor, pomba minha, imaculada minha, porque a minha cabeça está cheia de orvalho, os meus cabelos das gotas da noite.'),
('acf','ct',5,3,'Já despi a minha roupa; como a tornarei a vestir? Já lavei os meus pés; como os tornarei a sujar?'),
('acf','ct',5,4,'O meu amado pôs a sua mão pela fresta da porta, e as minhas entranhas estremeceram por amor dele.'),
('acf','ct',5,5,'Eu me levantei para abrir ao meu amado, e as minhas mãos gotejavam mirra, e os meus dedos mirra com doce aroma, sobre as aldravas da fechadura.'),
('acf','ct',5,6,'Eu abri ao meu amado, mas já o meu amado tinha se retirado, e tinha ido; a minha alma desfaleceu quando ele falou; busquei-o e não o achei, chamei-o e não me respondeu.'),
('acf','ct',5,7,'Acharam-me os guardas que rondavam pela cidade; espancaram-me, feriram-me, tiraram-me o manto os guardas dos muros.'),
('acf','ct',5,8,'Conjuro-vos, ó filhas de Jerusalém, que, se achardes o meu amado, lhe digais que estou enferma de amor.'),
('acf','ct',5,9,'Que é o teu amado mais do que outro amado, ó tu, a mais formosa entre as mulheres? Que é o teu amado mais do que outro amado, que tanto nos conjuras?'),
('acf','ct',5,10,'O meu amado é branco e rosado; ele é o primeiro entre dez mil.'),
('acf','ct',5,11,'A sua cabeça é como o ouro mais apurado, os seus cabelos são crespos, pretos como o corvo.'),
('acf','ct',5,12,'Os seus olhos são como os das pombas junto às correntes das águas, lavados em leite, postos em engaste.'),
('acf','ct',5,13,'As suas faces são como um canteiro de bálsamo, como flores perfumadas; os seus lábios são como lírios gotejando mirra com doce aroma.'),
('acf','ct',5,14,'As suas mãos são como anéis de ouro engastados de berilo; o seu ventre como alvo marfim, coberto de safiras.'),
('acf','ct',5,15,'As suas pernas como colunas de mármore, colocadas sobre bases de ouro puro; o seu aspecto como o Líbano, excelente como os cedros.'),
('acf','ct',5,16,'A sua boca é muitíssimo suave; sim, ele é totalmente desejável. Tal é o meu amado, e tal o meu amigo, ó filhas de Jerusalém.'),
('acf','ct',6,1,'Para onde foi o teu amado, ó mais formosa entre as mulheres? Para onde se retirou o teu amado, para que o busquemos contigo?'),
('acf','ct',6,2,'O meu amado desceu ao seu jardim, aos canteiros de bálsamo, para apascentar nos jardins e para colher os lírios.'),
('acf','ct',6,3,'Eu sou do meu amado, e o meu amado é meu;ele apascenta entre os lírios.'),
('acf','ct',6,4,'Formosa és, meu amor, como Tirza, aprazível como Jerusalém, terrível como um exército com bandeiras.'),
('acf','ct',6,5,'Desvia de mim os teus olhos, porque eles me dominam. O teu cabelo é como o rebanho das cabras que aparecem em Gileade.'),
('acf','ct',6,6,'Os teus dentes são como o rebanho de ovelhas que sobem do lavadouro, e das quais todas produzem gêmeos, e não há estéril entre elas.'),
('acf','ct',6,7,'Como um pedaço de romã, assim são as tuas faces entre os teus cabelos.'),
('acf','ct',6,8,'Sessenta são as rainhas, e oitenta as concubinas, e as virgens sem número.'),
('acf','ct',6,9,'Porém uma é a minha pomba, a minha imaculada, a única de sua mãe, e a mais querida daquela que a deu à luz; viram-na as filhas e chamaram-na bem-aventurada, as rainhas e as concubinas louvaram-na.'),
('acf','ct',6,10,'Quem é esta que aparece como a alva do dia, formosa como a lua, brilhante como o sol, terrível como um exército com bandeiras?'),
('acf','ct',6,11,'Desci ao jardim das nogueiras, para ver os frutos do vale, a ver se floresciam as vides e brotavam as romãzeiras.'),
('acf','ct',6,12,'Antes de eu o sentir, me pôs a minha alma nos carros do meu nobre povo.'),
('acf','ct',6,13,'Volta, volta, ó Sulamita, volta, volta, para que nós te vejamos. Por que olhais para a Sulamita como para as fileiras de dois exércitos?'),
('acf','ct',7,1,'Quão formosos são os teus pés nos sapatos, ó filha do príncipe! Os contornos de tuas coxas são como jóias, trabalhadas por mãos de artista.'),
('acf','ct',7,2,'O teu umbigo como uma taça redonda, a que não falta bebida; o teu ventre como montão de trigo, cercado de lírios.'),
('acf','ct',7,3,'Os teus dois seios como dois filhos gêmeos de gazela.'),
('acf','ct',7,4,'O teu pescoço como a torre de marfim; os teus olhos como as piscinas de Hesbom, junto à porta de Bate-Rabim; o teu nariz como torre do Líbano, que olha para Damasco.'),
('acf','ct',7,5,'A tua cabeça sobre ti é como o monte Carmelo, e os cabelos da tua cabeça como a púrpura; o rei está preso nas galerias.'),
('acf','ct',7,6,'Quão formosa, e quão aprazível és, ó amor em delícias!'),
('acf','ct',7,7,'A tua estatura é semelhante à palmeira; e os teus seios são semelhantes aos cachos de uvas.'),
('acf','ct',7,8,'Dizia eu: Subirei à palmeira, pegarei em seus ramos; e então os teus seios serão como os cachos na vide, e o cheiro da tua respiração como o das maçãs.'),
('acf','ct',7,9,'E a tua boca como o bom vinho para o meu amado, que se bebe suavemente, e faz com que falem os lábios dos que dormem.'),
('acf','ct',7,10,'Eu sou do meu amado, e ele me tem afeição.'),
('acf','ct',7,11,'Vem, ó amado meu, saiamos ao campo, passemos as noites nas aldeias.'),
('acf','ct',7,12,'Levantemo-nos de manhã para ir às vinhas, vejamos se florescem as vides, se já aparecem as tenras uvas, se já brotam as romãzeiras; ali te darei os meus amores.'),
('acf','ct',7,13,'As mandrágoras exalam o seu perfume, e às nossas portas há todo o gênero de excelentes frutos, novos e velhos; ó amado meu, eu os guardei para ti.'),
('acf','ct',8,1,'Ah! quem me dera que foras como meu irmão, que mamou aos seios de minha mãe! Quando te encontrasse lá fora, beijar-te-ia, e não me desprezariam!'),
('acf','ct',8,2,'Levar-te-ia e te introduziria na casa de minha mãe, e tu me ensinarias; eu te daria a beber do vinho aromático e do mosto das minhas romãs.'),
('acf','ct',8,3,'A sua mão esquerda esteja debaixo da minha cabeça, e a sua direita me abrace.'),
('acf','ct',8,4,'Conjuro-vos, ó filhas de Jerusalém, que não acordeis nem desperteis o meu amor, até que queira.'),
('acf','ct',8,5,'Quem é esta que sobe do deserto, e vem encostada ao seu amado?
